    //Print Service
    var defaultFontSize = 10;

    // A credential of 0 / "0" means "not on file" and must not be printed.
    var hasCredentialValue = function (Value) {
        return Value != null && Value !== '' && Value != 0;
    };

    // Task 56803 - medication orders (Surgeon, Anesthesia, Pre-Admission, Lasik, YAG) print
    // Lic, AMSCA and DEA after the name. DEA/AMSCA originate on the user list rather than the
    // order row, and apply only to providers carrying the MD suffix (SuffixId 10).
    var getSurgeonCredentialsText = function (mitem) {
        mitem = mitem || {};
        var Parts = [];
        if (hasCredentialValue(mitem.LicenseNumber)) { Parts.push('Lic: ' + mitem.LicenseNumber); }
        var Credentials = getReviewerAmscaDea(mitem);
        if (Credentials.AMSCA) { Parts.push('AMSCA: ' + Credentials.AMSCA); }
        if (Credentials.DEA) { Parts.push('DEA: ' + Credentials.DEA); }
        // The two trailing spaces preserve the original gap before the "; date" segment.
        return Parts.length > 0 ? ', ' + Parts.join(', ') + '  ' : '  ';
    };

    // Returns { AMSCA, DEA } for the order's reviewer ('' when not on file / not an MD).
    var getReviewerAmscaDea = function (mitem) {
        mitem = mitem || {};
        // Prefer what the calling controller already resolved onto the row; only fall back
        // to the cached user list when the row does not carry the numbers.
        var AMSCA = mitem.AMSCA || mitem.AMSCAA || '';
        var DEA = mitem.DEA || '';
        if (!hasCredentialValue(AMSCA) || !hasCredentialValue(DEA)) {
            var allUserList = localStorageFactory.getItem("allUserList") || [];
            var Surgeonlist = $filter("filter")(allUserList, function (subitem) {
                return subitem.DoctorID == mitem.ReviewedBy && subitem.SuffixId == 10;
            }) || [];
            if (Surgeonlist.length > 0) {
                if (!hasCredentialValue(AMSCA)) { AMSCA = Surgeonlist[0].AMSCAA; }
                if (!hasCredentialValue(DEA)) { DEA = Surgeonlist[0].DEA; }
            }
        }
        return {
            "AMSCA": hasCredentialValue(AMSCA) ? AMSCA : '',
            "DEA": hasCredentialValue(DEA) ? DEA : ''
        };
    };
