    function getNewChiefComplaintwithRemarks(localArray) {
        var cFont = 9;
        if (localArray === undefined || localArray.length === 0)
            return;

        var bodyItem = [];
        var doctorinfo = eHnoteMasterDataService.getUserInfo();
        var SpecializationId = doctorinfo.doctordata.User[0].SpecializationId;

        if (SpecializationId === 2 || SpecializationId === 9) {
            angular.forEach(localArray, function (item) {
                item.ActiveInd = 'Y';
                item.OrganId = 4;
            });
        }
        var invItem1 = [{
            type: 'round',
            ul: [],
            fontSize: 10

        }];
        angular.forEach(localArray, function (item) {
            if (item.ActiveInd === 'Y') {
                var organName = item.OrganId === 1 ? 'Right Eye : ' : item.OrganId === 4 ? '' : item.OrganId === 2 ? 'Left Eye : ' : item.OrganId === 3 ? 'Both Eyes : ' : '';
                item.Remarks = item.Remarks || "";
                var Remarks = '';
                if (item.Remarks !== "") {
                    Remarks = 'Remarks : ';
                }

                if (item.ChiefComplaintName !== "") {
                    invItem1[0].ul.push({
                        text: [
                            { text: organName, color: 'black', bold: true, fontSize: cFont },
                            { text: item.ChiefComplaintName, color: 'black', bold: false, fontSize: cFont },
                            { text: Remarks, color: '#000000', bold: true, fontSize: 8 },
                            { text: item.Remarks, color: '#686868', bold: false, fontSize: 9 }

                        ], margin: [0, 2, 0, 5]
                    });

                }
            }
        });
        if (invItem1.length != 0) {
            bodyItem.push(invItem1);

            var patientLabTestTable = {
                style: 'tableExample1',
                table: {
                    //widths: [120, 5, 410],
                    widths: ['*'],
                    body: bodyItem
                },
                layout: {
                    hLineWidth: function (i, node) {
                        return (i === 0 || i === node.table.body.length) ? 0.1 : 0.1;
                    },
                    vLineWidth: function (i, node) {
                        return (i === 0 || i === node.table.widths.length) ? 0.5 : 0.5;
                    },
                    hLineColor: function (i, node) {
                        return (i === 0 || i === node.table.body.length) ? 'white' : 'white';
                    },
                    vLineColor: function (i, node) {
                        return (i === 0 || i === node.table.widths.length) ? 'white' : 'white';
                    }
                }
            };
            return patientLabTestTable;
        }
    }
