    this.GenerateAddPatientConsentDocumentPrint = function (scopeObj) {

        var content = [];
        //if (scopeObj.htmlcontent && scopeObj.htmlcontent.length > 0) {
        //    angular.forEach(scopeObj.htmlcontent, function (hitem) {
        //        content.push(hitem);
        //    });
        //}
        if (scopeObj.htmlcontent && scopeObj.htmlcontent.length > 0) {
            angular.forEach(scopeObj.htmlcontent, function (hitem) {
                if (hitem && typeof hitem === 'object') {
                    // Remove float — pdfmake cannot handle it and produces NaN
                    if (hitem.style) {
                        hitem.style = hitem.style.filter(function (s) {
                            return s !== 'float';
                        });
                    }
                    // Fix any NaN numeric properties
                    ['fontSize', 'lineHeight', 'margin', 'width', 'height'].forEach(function (prop) {
                        if (hitem[prop] !== undefined && isNaN(hitem[prop])) {
                            delete hitem[prop];
                        }
                    });
                }
                content.push(hitem);
            });
        }

        // ── pdfHeader is now a function (same as openPrintPreview) or null ────
        var headerFn = scopeObj.pdfHeader || null;   // function(currentPage, pageCount) or null
        var hasHeader = scopeObj.hasHeader || false;
        var consentName = scopeObj.consentName || '';
        var topMargin = scopeObj.topMargin || (hasHeader ? 130 : 40);
        var docDefinition = {
            pageSize: 'A4',
            //pageMargins: [40, hasHeader ? 90 : 40, 40, 60],
            pageMargins: [40, topMargin, 40, 60],


            // Pass the function directly — pdfMake calls it per page
            header: headerFn,

            footer: function (currentPage, pageCount) {
                return {
                    margin: [40, 5, 40, 10],
                    columns: [
                        { text: '', fontSize: 8 },
                        {
                            text: 'Page ' + currentPage + ' of ' + pageCount,
                            alignment: 'right',
                            fontSize: 9,
                            color: '#333333'
                        }
                    ]
                };
            },

            content: content,

            pageBreakBefore: function (currentNode) {
                return currentNode.style &&
                    currentNode.style.indexOf('pdf-pagebreak-before') > -1;
            },

            defaultStyle: {
                font: 'Roboto',
                fontSize: 10,
                lineHeight: 1.4
            },

            styles: {
                "header": { "fontSize": 18, "bold": true, "margin": [0, 0, 0, 8] },
                "subheader": { "fontSize": 14, "bold": true, "margin": [0, 10, 0, 5] },
                "tableHeader": { "bold": true, "fontSize": 10, "color": "black" },
                "contentText": { "fontSize": 10 },
                "tableExample": { "margin": [0, 5, 0, 8] }
            }
        };

        return docDefinition;
    };

