    this.generateConsultationEntryFormForAll1 = function (scopeobj) {
        var doctorinfo = eHnoteMasterDataService.getUserInfo();
        var patientinfo = eHnoteMasterDataService.getAppointmentInfo();
        var appointmentinfo = eHnoteMasterDataService.getAppointmentInfo();
        var printSettingInfo = eHnoteMasterDataService.getPrintSettingSpecific("OT").PageSettings;
        var emptyRow = getEmptyTable();

        var data = printSettings;
        var pageSettings = {
            "marginLeft": 40,
            "marginTop": 100,
            "marginRight": 40,
            "marginBottom": 10
        };
        var headerHeight = 100;
        var footerHeight = 100;
        var docSign = "";
        var isDefaultDocSign = "";
        printPageSize = "A4";
        contentSetting = setContentSettings();
        if (data !== undefined) {
            pageSettings = data.JsonSetting.pageSettings;
            headerHeight = data.JsonSetting.clinicSettings.headerSettings.dimension.height;
            footerHeight = data.JsonSetting.clinicSettings.footerSettings.dimension.height;
            contentSetting = data.JsonSetting.clinicSettings.contentSettings;
            docSign = data.JsonSetting.clinicSettings.footerSettings.custFootSign;
            isDefaultDocSign = data.JsonSetting.clinicSettings.footerSettings.isFootSignDefault;
            if (printSettingInfo.PageSize === "A4") {
                defaultFontSize = 10;
            } else {
                printPageSize = "A4";
                defaultFontSize = 10;
            }
        }
        var content = [];
        var cFont = 7;
        var cBold = true;

        var branchName = "";
        if (doctorinfo.doctordata.UserAddress.length > 0) {
            branchName = doctorinfo.doctordata.UserAddress[0].ClinicName;
        }

        var HospitalName = "";

        HospitalName = branchName;

        //scopeobj.PatientAppointmentDetails = $filter("filter")(scopeobj.PatientAppointmentDetails, function (titem) { return titem.AppointmentStatus !== "C"; });

        angular.forEach(scopeobj.PatientAppointmentDetails, function (pitem, index) {

            var filteredArray = $filter("filter")(scopeobj.OPAppointmentDetails, function (titem) { return titem.AppointmentID === pitem.AppointmentID; });
            filteredArray = filteredArray || [];
            if (filteredArray.length > 0) {
                pitem.PatientInsuranceList = filteredArray[0].PatientInsuranceList;
                pitem.PCPReferenceNumber = filteredArray[0].PCPReferenceNumber;
                pitem.PCPSecondReferenceNumber = filteredArray[0].PCPSecondReferenceNumber;
                pitem.PCPDoctorName = filteredArray[0].PCPDoctorName;
                pitem.PcpNPI = filteredArray[0].PcpNPI;
                pitem.Authorization = filteredArray[0].PreAuthNumber1;
                pitem.PreAuthorizationCode = filteredArray[0].PreAuthorizationCode;
                pitem.OtherNotes = filteredArray[0].OtherNotes;
                pitem.PreAuthorizationNumber = "";
                if (filteredArray[0].PreAuthDetails && filteredArray[0].PreAuthDetails.length > 0) {
                    pitem.PreAuthorizationNumber = filteredArray[0].PreAuthDetails[0].PreAuthorizationNumber;
                }
            }

            var PatientInfoPrint = getPatientInfoDataForAll2(pitem, index);
            if (PatientInfoPrint !== "" || PatientInfoPrint !== undefined) {
                content.push(PatientInfoPrint);
            }
        });

        var newsomeDate = $filter('date')(new Date(), "MM-dd-yyyy hh:mm:a");

        var docdefination = {
            content: content,
            footer: {
                columns: [
                    { text: 'Printed by ' + scopeobj.CreatedBy + '  ' + newsomeDate, alignment: 'right', fontSize: 7, margin: [0, 0, 15, 0] }
                ]
            },
            defaultStyle: {
                font: "Roboto"
            },
            pageSize: 'LETTER',
            pageOrientation: 'portrait',//portrait landscape
            pageMargins: [10, 10, 20, 20],
            styles: {
                tableExample: {
                    margin: [0, 5, 0, 5]
                }
            }
        };
        pdfMake.createPdf(docdefination).print();

    }

