    function getCM(sur) {
        if (!sur || sur.length === 0) {
            return [];
        }
        let PSMArray = [];
        let obj = {
            "Medications": sur || []
        }
        let MedicationName = "";
        let SIG = "";
        var MedInstructions = "";
        let medtype = "";
        if (obj.Medications.length > 0) {

            var MedicationsBody = [];



            angular.forEach(obj.Medications, function (item) {
                MedicationName = ""; SIG = ""; MedInstructions = "";
                if (item.MedicationType == 'Stop') {
                    medtype = "Stopped Medications :";


                    MedicationName = item.MedicineName || "";
                    if (item.Sig == "") {
                        SIG += (item.Action != "") ? item.Action : "";
                        SIG += (item.Dose != "") ? " " + item.Dose : "";
                        SIG += (item.DoseUnit != "") ? " " + item.DoseUnit : "";
                        SIG += (item.Route != "") ? " " + item.Route : "";
                        SIG += (item.Frequency != "") ? " " + item.Frequency : "";
                        SIG += (item.DoseOther != "") ? " " + item.DoseOther : "";
                        SIG += (item.DaysSupply != "") ? " " + item.DaysSupply : "";
                    } else {
                        SIG = item.Sig;
                    }
                    MedInstructions = item.PatientInstructions || "";
                    var startdate = '';
                    var starttime = '';
                    if (item.StartDate != '') {
                        startdate = $filter('date')(new Date(item.StartDate), "MM-dd-yyyy") || '';
                    }
                    if (item.StartTime != '') {
                        starttime = $filter('date')(new Date(item.StartTime), "h:mm a") || '';
                        /*starttime = $filter("date")(new Date(item.StartTime), "h:mm a") || "",*/
                    }
                    if (item.StopDate != '') {
                        stopdate = $filter('date')(new Date(item.StopDate), "MM-dd-yyyy") || '';
                    }
                    if (item.EndTime != '') {
                        stoptime = $filter('date')(new Date(item.EndTime), "h:mm a") || '';
                    }

                    /* let startdate = item.StartDate*/


                    MedicationsBody.push([
                        { text: medtype, color: "black", fontSize: 10, bold: true, margin: [2, 0, 0, 0] },
                        { text: MedicationName, color: "black", fontSize: 10, bold: false, margin: [2, 0, 0, 0] },
                        { text: "StartDate: " + startdate + '' + "StartDate: " + stopdate, color: "black", fontSize: 10, bold: false, margin: [2, 0, 0, 0] },
                        { text: "Intructions: " + MedInstructions, color: "black", fontSize: 10, bold: false, margin: [2, 0, 0, 5] }
                    ]);
                } else {
                    medtype = "Continuation Medications :";

                    MedicationName = item.MedicineName || "";
                    if (item.Sig == "") {
                        SIG += (item.Action != "") ? item.Action : "";
                        SIG += (item.Dose != "") ? " " + item.Dose : "";
                        SIG += (item.DoseUnit != "") ? " " + item.DoseUnit : "";
                        SIG += (item.Route != "") ? " " + item.Route : "";
                        SIG += (item.Frequency != "") ? " " + item.Frequency : "";
                        SIG += (item.DoseOther != "") ? " " + item.DoseOther : "";
                        SIG += (item.DaysSupply != "") ? " " + item.DaysSupply : "";
                    } else {
                        SIG = item.Sig;
                    }
                    MedInstructions = item.PatientInstructions || "";

                    MedicationsBody.push([
                        { text: medtype, color: "black", fontSize: 10, bold: true, margin: [2, 0, 0, 0] },
                        { text: MedicationName, color: "black", fontSize: 10, bold: false, margin: [2, 0, 0, 0] },
                        { text: "SIG: " + SIG, color: "black", fontSize: 10, bold: false, margin: [2, 0, 0, 0] },
                        { text: "Intructions: " + MedInstructions, color: "black", fontSize: 10, bold: false, margin: [2, 0, 0, 5] }
                    ]);
                }

            });
            PSMArray = [{
                table: {
                    widths: ['*', 400],
                    body: [
                        [{ text: 'Current Medications', fontSize: 10, bold: true, margin: [5, 0, 0, 0], border: [true, false, true, true], alignment: 'right' },
                        {
                            stack: MedicationsBody, border: [false, false, true, true], alignment: 'left',
                            bold: false,
                            fontSize: 8
                        }]
                    ]
                },
                /* layout: 'lightHorizontalLines'*/
            }];

        }

        return PSMArray;
    }
    function getLAB(sur) {
        if (!sur || sur.length === 0) {
            return [];
        }
        let LABArray = [];
        let obj = {
            "LABINV": sur || []
        }
        let InvestigationName = "";

        var InvestigationNotes = "";

        if (obj.LABINV.length > 0) {

            var LABINVBody = [];

            /*OrganId*/

            angular.forEach(obj.LABINV, function (item) {
                InvestigationName = ""; InvestigationNotes = "";
                var organName = item.OrganId === 1 ? 'Right Eye : ' : item.OrganId === 4 ? '' : item.OrganId === 2 ? 'Left Eye : ' : item.OrganId === 3 ? 'Both Eyes : ' : '';
                InvestigationName += '-' + organName || '';
                InvestigationName = item.ProcedureCode || "";
                InvestigationName += '-' + item.InvestigationName.toUpperCase() || "";
                InvestigationNotes = ' Notes:' + item.InvestigationNotes || "";


                var Duartionlist = "";
                var list1 = "";
                var list2 = "";
                item.Duration = item.Duration || 0;
                if (item.Duration != 0) {
                    list1 = ' since ' + item.Duration;
                    list2 = item.DurationType === 'D' ? 'Day(s)' : (item.DurationType === 'W' ? 'Week(s)' : (item.DurationType === 'M' ? 'Month(s)' : (item.DurationType === 'Y' ? 'Year(s)' : '')));
                    InvestigationName += '  ' + list1 + list2;
                } else if (item.Duration == 0 && item.DurationType != '') {
                    list2 = item.DurationType === 'D' ? 'Day(s)' : (item.DurationType === 'W' ? 'Week(s)' : (item.DurationType === 'M' ? 'Month(s)' : (item.DurationType === 'Y' ? 'Year(s)' : '')));
                    InvestigationName += '  ' + list2
                }

                if (item.DurationDate != '') {
                    var shDurationDate = $filter('date')(new Date(item.DurationDate), "MM-dd-yyyy") || "";

                    InvestigationName += '  (Scheduled on ' + shDurationDate + ')';
                } else {
                    shDurationDate = '';
                }

                LABINVBody.push([
                    { text: InvestigationName, color: "black", fontSize: 10, bold: true, margin: [2, 0, 0, 0] },
                    { text: InvestigationNotes, color: "black", fontSize: 10, bold: false },

                ]);
            });
            LABArray = [{
                table: {
                    widths: ['*', 400],
                    body: [
                        [{ text: 'Labs/Investigations', fontSize: 10, bold: true, margin: [5, 0, 0, 0], border: [true, false, true, true], alignment: 'right' },
                        {
                            stack: LABINVBody, border: [false, false, true, true], alignment: 'left',
                            bold: false,
                            fontSize: 8
                        }]
                    ]
                },
                /* layout: 'lightHorizontalLines'*/
            }];

        }

        return LABArray;
    }
