    function getPreOpCallDetails(data) {
        if (!data || data.length === 0) {
            return [];
        }
        var PreOpCalltable = [];
        var PreOpCallarray = [];
        if (data.length > 0) {
            data.forEach(function (item) {
                var ContactStartDate = "";
                if (item.ContactStartDate != '') {
                    ContactStartDate = $filter('date')(new Date(item.ContactStartDate), "MM-dd-yyyy") || "";

                    /*Systmicstring += ' Onset ' + shDurationDate;*/
                } else {
                    ContactStartDate = '';
                }
                var ContactStartTime = '';
                if (item.ContactStartTime != '') {
                    /*  ContactStartTime = $filter("date")(new Date(item.ContactStartTime), "h:mm a") || "";*/
                    ContactStartTime = item.ContactStartTime || "";
                } else {
                    ContactStartTime = ""
                }
                var contacttype = '';
                if (item.ContactType != '') {
                    contacttype = item.ContactType || "";
                } else {
                    contacttype = "";
                }
                var preopinstructions = "";
                if (!item.IsNoResponse) {
                    if (item.IsConnectedWithPatient) {
                        preopinstructions = "Connected with Patient" || "";
                    }
                    if (item.IsConnectedWithFamilyOrFriend) {
                        preopinstructions += "Connected with Family/Patient" || "";
                    }
                    if (item.IsLeftMsgWithFamilyOrFriend) {
                        preopinstructions += "Left Message With family/friends" || "";
                    }
                    if (item.IsLeftMsgWithPatient) {
                        preopinstructions += "Left Message With Patient" + " and shared instructions about" || "";
                    }
                    if (item.IsAccompanyShared) {
                        preopinstructions += "accompany," || "";
                    }
                    if (item.IsArrivalTimeShared) {
                        preopinstructions += "time of arrival," || "";
                    }
                    if (item.IsDrinkPlentyWaterShared) {
                        preopinstructions += "water Intake," || "";
                    }
                    if (item.IsNpoAfterMidnightShared) {
                        preopinstructions += " diet," || "";
                    }
                    if (item.IsTakeBpHeartMedShared || item.IsDoNotTakeBpMedShared) {
                        preopinstructions += "Medications," || "";
                    }
                    if (item.IsNoMakeupJewelMoistShared) {
                        preopinstructions += "No Makeup and Jewelry," || "";
                    }
                    if (item.IsCoPay) {
                        preopinstructions += "Co-Pay," || "";
                    }
                    preopinstructions = preopinstructions.replace(/,\s*$/, "");
                } else {
                    preopinstructions = " No Response" || "";
                }
                var StartDropsDate = ''; var StartDropsTime = ''; var EyeDropNotes = ''; var Remarks = '';
                StartDropsDate = $filter('date')(new Date(item.DropStartDate), "MM-dd-yyyy") || "";
                StartDropsTime = $filter("date")(new Date(item.DropsStartTime), "h:mm a") || "";
                EyeDropNotes = item.CoPayNotes || "";
                Remarks = item.Remarks || "";

                PreOpCalltable.push([
                    /* { text: 'Date : ', fontSize: 10, bold: true, alignment: 'left' },*/
                    { text: 'Date : ' + ContactStartDate + ' Time : ' + ContactStartTime + ' Contacted : ' + contacttype, fontSize: 10, bold: false, alignment: 'left' },
                    /*{ text: 'Time : ', fontSize: 10, bold: true, border: [false, false, false, false], alignment: 'left' }, { text: ContactStartTime, fontSize: 10, bold: false, alignment: 'left', border: [false, false, false, false] },*/
                    /*                    { text: 'Contacted : ', fontSize: 10, bold: true, border: [false, false, false, false], alignment: 'left' }, { text: contacttype, fontSize: 10, bold: false, alignment: 'left', border: [false, false, false, false] },*/
                    { text: preopinstructions, fontSize: 10, bold: false, alignment: 'left', border: [false, false, false, false] }, /*{ text: EyeDropNotes, fontSize: 10, bold: false, alignment: 'left', border: [false, false, false, false] },*/
                    { text: 'Remarks : ' + Remarks, fontSize: 10, bold: true, border: [false, false, false, false] },
                    /*            { text: Remarks, fontSize: 10, bold: false, alignment: 'left', border: [false, false, false, false], width: 350 },*/
                ]);

            });
            PreOpCallarray = [{
                table: {
                    widths: ['*', 400],
                    body: [
                        [{
                            text: 'Pre-Op Call', fontSize: 10, bold: true, margin: [5, 0, 0, 0], border: [true, true, true, true], alignment: 'right'
                        },
                        {
                            stack: PreOpCalltable, border: [false, true, true, true], alignment: 'left',
                            bold: false,
                            fontSize: 8
                        }]
                    ]
                },
                /*   layout: 'lightHorizontalLines'*/
            }];
        }
        return PreOpCallarray;

    }
