    this.GenerateLabsAndStudiesPrint = function (obj) {
        let content = [];
        content.push(getPatientBranchDetailsTableForASC(obj));
        content.push(getPatientDetailsTable());
        content.push(getPatientDetailsTableForASC(obj));
        content.push(getPatientSurgeryDetailsTable());
        content.push(getPatientSurgeryDetailsTableForASC(obj));

        content.push({ text: 'Labs & Studies', alignment: 'center', bold: true, fontSize: 14, margin: [0, 10, 0, 8] });

        if (obj.Laboratories && obj.Laboratories.length > 0) {
            content.push(getLabsAndStudiesSectionInfoTable('Laboratories'));
            content.push(getLabsAndStudiesListData((obj.Laboratories || []).map(function (item) {
                return item.Name;
            })));
        }
        
        if (obj.ExaminationOrders && obj.ExaminationOrders.length > 0) {
            content.push(getLabsAndStudiesSectionInfoTable('Examination Orders'));
            content.push(getLabsAndStudiesListData((obj.ExaminationOrders || []).map(function (item) {
                return item.Name;
            })));
        }
        
        if (obj.CoordinatorChecklist && obj.CoordinatorChecklist.length > 0) {
            content.push(getLabsAndStudiesSectionInfoTable('Coordinator Checklist'));
            content.push(getLabsAndStudiesListData((obj.CoordinatorChecklist || []).map(function (item) {
                return item.Name + ': ' + (item.Value || '-');
            })));
        }

        // Reviewed By: name, Lic, AMSCA, DEA ; saved Reviewed Date - only the reviewers that were selected
        let ReviewedByLines = [];
        if (obj.DoctorReviewedBy) {
            ReviewedByLines.push(getLabsAndStudiesReviewedByLine('Doctor Reviewed By:', obj.DoctorReviewedBy));
        }
        if (obj.CoordinatorReviewedBy) {
            ReviewedByLines.push(getLabsAndStudiesReviewedByLine('Coordinator Reviewed By:', obj.CoordinatorReviewedBy));
        }
        // Patient / Guardian signature: "Patient - Name" then the Topaz image (same image block as the discharge patient signature)
        if (obj.PatientGuardianSignature && obj.PatientGuardianSignature.SignString) {
            ReviewedByLines.push({
                stack: [
                    { text: 'Patient / Guardian Signature:', bold: true },
                    { text: obj.PatientGuardianSignature.SignerType + ' - ' + obj.PatientGuardianSignature.SignerName },
                    { image: obj.PatientGuardianSignature.SignString, width: 100, height: 50, alignment: 'left', margin: [0, 2, 0, 0] }
                ],
                fontSize: 10,
                margin: [0, 0, 0, 6]
            });
        }
        if (ReviewedByLines.length > 0) {
            content.push({ stack: ReviewedByLines, margin: [15, 0, 0, 15] });
        }

        let docdefination = {
            content: content,
            defaultStyle: {
                font: "Roboto"
            },
            pageSize: 'LETTER',
            pageOrientation: 'portrait',
            pageMargins: [25, 10, 25, 20],
            styles: {
                tableExample: {
                    margin: [0, 5, 0, 15]
                },
            },
        }
        pdfMake.createPdf(docdefination).print();
    };

    // grey section bar, same style as getnewAssessmentInfoTable / getnewDoctorSignatureInfoTable
    function getLabsAndStudiesSectionInfoTable(title) {
        return {
            margin: [0, 0, 0, 0],
            style: 'tableExample',
            table: {
                widths: '*',
                body: [[{ text: title, alignment: 'left', bold: true, fontSize: 10, fillColor: '#d3d3d8', margin: [5, 0, 0, 0] }]]
            },
            layout: 'noBorders'
        };
    }

    // numbered list under a section bar; "None" when the section is empty
    function getLabsAndStudiesListData(lines) {
        if (!lines || lines.length === 0) {
            return { text: 'None', fontSize: 10, color: 'gray', margin: [15, 0, 0, 15] };
        }
        return { ol: lines, fontSize: 10, margin: [15, 0, 0, 15] };
    }

    // "Label:" then "Name, Lic: .., AMSCA: .., DEA: .. ; MM-dd-yyyy hh:mm a", same text as the order "Signed by" lines.
    // item = { ReviewedBy, ReviewedByName, LicenseNumber, ReviewedByDateTime }
    function getLabsAndStudiesReviewedByLine(label, item) {
        let ReviewedDt = '';
        if (item.ReviewedByDateTime) {
            // saved as "yyyy-MM-dd HH:mm:ss" on the summary or returned as ISO by the API; moment reads both
            ReviewedDt = moment(item.ReviewedByDateTime).format("MM-DD-YYYY hh:mm A");
        }
        return {
            stack: [
                { text: label, bold: true },
                { text: (item.ReviewedByName || '') + getSurgeonCredentialsText(item).replace(/\s+$/, '') + (ReviewedDt ? ' ; ' + ReviewedDt : '') }
            ],
            fontSize: 10,
            margin: [0, 0, 0, 6]
        };
    }

