    function getnewMedicalReconSignedDetails(UserFullName, LicenseNumber, CurrentDate) {
        var hFont = 10;
        var NameHeader = '';
        var LicenseHeader = '';
        var CurrentDateHeader = '';
        UserFullName = UserFullName || '';
        LicenseNumber = LicenseNumber || '';
        CurrentDate = CurrentDate || "";

        if (UserFullName != '') {
            NameHeader = 'Doctor Name :';
        }
        if (LicenseNumber != '') {
            LicenseHeader = 'Lic :';
        }
        if (CurrentDate != '') {
            CurrentDateHeader = 'Date :';
        }
        var bodyItem = [];
        var patientHeadingArray = [];
        patientHeadingArray.push({
            text: [
                { text: NameHeader + '  ', alignment: 'left', bold: true, fontSize: hFont, margin: [5, 0, 0, 0] },
                { text: UserFullName + '  ', alignment: 'left', fontSize: hFont, margin: [5, 0, 0, 0] },
                { text: LicenseHeader + ' ', alignment: 'left', bold: true, fontSize: hFont, margin: [5, 0, 0, 0] },
                { text: LicenseNumber + ' ', alignment: 'left', fontSize: hFont, margin: [5, 0, 0, 0] },
                { text: CurrentDateHeader + '  ', alignment: 'left', bold: true, fontSize: hFont, margin: [5, 0, 0, 0] },
                { text: CurrentDate, alignment: 'left', fontSize: hFont, margin: [5, 0, 0, 0] },

            ]
        });
        bodyItem.push(patientHeadingArray);
        var patientLabTestTable = {
            style: 'tableExample',
            table: {
                widths: '*',
                body: bodyItem
            },
            layout: 'noBorders'
        };

        return patientLabTestTable;
    }

