    function Card(title, value) {
        return {
            table: {
                width: 90,
                widths: ['*'],
                body: [
                    [
                        {
                            text: title,
                            fontSize: 9,
                            bold: true,
                            color: 'gray',
                            fillColor: '#F3F3F3',
                            alignment: 'center',
                            margin: [0, 3, 0, 3]
                        }
                    ],
                    [
                        {
                            text: value || ' ',
                            fontSize: 10,
                            bold: true,
                            alignment: 'center',
                            margin: [0, 5, 0, 5]
                        }
                    ]
                ]
            },
            layout: {
                hLineWidth: function () { return 0.5; },
                vLineWidth: function () { return 0.5; },
                hLineColor: function () { return '#CCCCCC'; },
                vLineColor: function () { return '#CCCCCC'; }
            }
        };
    }

    function HasNineGazeData(eyeObj) {

        if (!eyeObj) return false;

        var positions = [
            eyeObj.UpLeft,
            eyeObj.Up,
            eyeObj.UpRight,
            eyeObj.Left,
            eyeObj.Primary,
            eyeObj.Right,
            eyeObj.DownLeft,
            eyeObj.Down,
            eyeObj.DownRight
        ];

        for (var i = 0; i < positions.length; i++) {

            var p = positions[i];

            if (!p) continue;

            if ((p.H && (p.H.Amount || p.H.Direction)) ||
                (p.V && (p.V.Amount || p.V.Direction))) {
                return true;
            }
        }

        return false;
    }

    function AddSection(A1, title, content) {

        if (!content) {
            console.log("Missing content for:", title);
            return;
        }

        A1.push([

            {
                text: title,
                fillColor: "#F1F1F1",
                bold: true,
                fontSize: 11,
                alignment: "left",
                margin: [5, 8, 5, 5],
                border: [false, true, true, true]
            },

            content

        ]);

    }

    function getNineGazeExtraOcularData(Object, ODDistanceInd, ODNearInd) {

        var bodyItem = [];

        if (!Object || Object.length == 0)
            return bodyItem;


        angular.forEach(Object, function (item) {
            var A1 = [];
            if (item.InvestigationId != 695)
                return;

            var hasDistance =
                HasNineGazeData(item.ODDistance);

            var hasNear =
                HasNineGazeData(item.ODNear);

            if (!hasDistance && !hasNear) {
                return;
            }

            //Alphabet Pattern
            if (item.AlphabetPattern) {

                AddSection(A1, "Alphabet Pattern", {
                    text: item.AlphabetPattern,
                    margin: [5, 8, 0, 8],
                    border: [false, true, false, true],
                    fontSize: 11
                });

            }

            //Distance Section

            if (hasDistance) {
                var DistanceItems = [];
                DistanceItems.push([
                    {
                        stack: EyeHeader("", ODDistanceInd)
                    }
                ]);

                //DISTANCE - OD
                var ODDistanceStack = [];

                /*************** Row-1 ****************/

                ODDistanceStack.push(

                    CreateNineGazeRow(

                        "UP LEFT", item.ODDistance.UpLeft,

                        "UP", item.ODDistance.Up,

                        "UP RIGHT", item.ODDistance.UpRight,

                        item.DistanceMeasuredUnit

                    )

                );

                /*************** Row-2 ****************/

                ODDistanceStack.push({

                    margin: [0, 15, 0, 0],

                    stack: [

                        CreateNineGazeRow(

                            "LEFT", item.ODDistance.Left,

                            "PRIMARY", item.ODDistance.Primary,

                            "RIGHT", item.ODDistance.Right,

                            item.DistanceMeasuredUnit

                        )

                    ]

                });

                /*************** Row-3 ****************/

                ODDistanceStack.push({

                    margin: [0, 15, 0, 0],

                    stack: [

                        CreateNineGazeRow(

                            "DOWN LEFT", item.ODDistance.DownLeft,

                            "DOWN", item.ODDistance.Down,

                            "DOWN RIGHT", item.ODDistance.DownRight,

                            item.DistanceMeasuredUnit

                        )

                    ]

                });

                DistanceItems.push([

                    {
                        stack: ODDistanceStack
                    }

                ]);
                AddSection(A1, "Distance", {

                    table: {
                        widths: ['*'],
                        body: DistanceItems
                    },
                    layout: "noBorders",
                    border: [false, true, false, true]

                });

                if (item.DistanceRemarks) {

                    AddSection(A1, "", {
                        text: "Notes : " + item.DistanceRemarks,
                        margin: [5, 8, 0, 8],
                        border: [false, true, false, true],
                    });

                }

            }

            if (hasNear) {
                //Near Section

                var NearItems = [];
                NearItems.push([
                    {
                        stack: EyeHeader("", ODNearInd)
                    }
                ]);


                //NEAR - OD
                var ODNearStack = [];

                /*************** Row-1 ****************/

                ODNearStack.push(

                    CreateNineGazeRow(

                        "UP LEFT", item.ODNear.UpLeft,

                        "UP", item.ODNear.Up,

                        "UP RIGHT", item.ODNear.UpRight,

                        item.DistanceMeasuredUnit

                    )

                );

                /*************** Row-2 ****************/

                ODNearStack.push({

                    margin: [0, 15, 0, 0],

                    stack: [

                        CreateNineGazeRow(

                            "LEFT", item.ODNear.Left,

                            "PRIMARY", item.ODNear.Primary,

                            "RIGHT", item.ODNear.Right,

                            item.DistanceMeasuredUnit

                        )

                    ]

                });

                /*************** Row-3 ****************/

                ODNearStack.push({

                    margin: [0, 15, 0, 0],

                    stack: [

                        CreateNineGazeRow(

                            "DOWN LEFT", item.ODNear.DownLeft,

                            "DOWN", item.ODNear.Down,

                            "DOWN RIGHT", item.ODNear.DownRight,

                            item.DistanceMeasuredUnit

                        )

                    ]

                });


                NearItems.push([

                    {
                        stack: ODNearStack
                    }

                ]);

                AddSection(A1, "Near", {

                    table: {
                        widths: ['*'],
                        body: NearItems
                    },
                    layout: "noBorders",
                    border: [false, true, false, true]

                });

                if (item.NearRemarks) {

                    AddSection(A1, "", {
                        text: "Notes : " + item.NearRemarks,
                        margin: [5, 8, 0, 8],
                        border: [false, true, false, true],
                    });

                }

            }

            if (A1.length > 0) {

                bodyItem.push({

                    table: {

                        widths: [70, '*'],
                        body: A1

                    },

                    layout: {
                        hLineWidth: function () { return 0.5; },
                        vLineWidth: function () { return 0.5; },
                        hLineColor: function () { return '#D9D9D9'; },
                        vLineColor: function () { return '#D9D9D9'; }
                    },

                    margin: [0, 10, 0, 10]

                });

            }
        });



        return bodyItem;

    }

    function EyeHeader(title, freelyMoving) {

        var stack = [];

        stack.push({

            text: title,

            alignment: 'center',

            bold: true,

            fontSize: 14,

            margin: [0, 5, 0, 8]

        });

        if (freelyMoving) {

            stack.push({

                text: "Full And Freely Moving In All Directions",
                alignment: 'center',
                italics: true,
                fontSize: 9,
                color: "#666666",
                margin: [0, 5, 0, 10]

            });

        }

        return stack;

    }

    function NineGazeCard(title, obj, measuredUnit) {

        obj = obj || {};

        return {
            table: {

                widths: ['*'],

                body: [

                    [
                        {
                            text: title,
                            bold: true,
                            alignment: 'center',
                            fontSize: 9,
                            color: '#555',
                            margin: [0, 6, 0, 6]
                        }
                    ],

                    [
                        {
                            stack: [

                                HVRow("H", obj.H, measuredUnit),

                                {
                                    margin: [0, 2, 0, 0],
                                    columns: HVRow("V", obj.V, measuredUnit).columns
                                }

                            ],

                            margin: [10, 14, 10, 14]
                        }
                    ]

                ]

            },

            layout: {

                hLineWidth: function () { return .5; },
                vLineWidth: function () { return .5; },
                hLineColor: function () { return '#D8D8D8'; },
                vLineColor: function () { return '#D8D8D8'; }

            }

        };

    }

    function HVRow(label, data, measuredUnit) {

        data = data || {};

        return {
            columns: [
                {
                    width: 12,
                    text: label,
                    bold: true,
                    color: '#8A8F9C',
                    fontSize: 8
                },
                {
                    width: 28,
                    text: (data.Amount != null && data.Amount !== '') ? data.Amount : ' ',
                    bold: true,
                    fontSize: 8
                },
                {
                    width: 20,
                    text: measuredUnit || 'PD',
                    bold: true,
                    color: '#8A8F9C',
                    fontSize: 8
                },
                {
                    width: '*',
                    text: data.Direction || ' ',
                    fontSize: 8,
                    color: '#666666'
                }
            ]
        };

    }

    function CreateNineGazeRow(leftTitle, leftObj,
        middleTitle, middleObj,
        rightTitle, rightObj,
        measuredUnit) {
        measuredUnit = (measuredUnit == "Degree") ? "D" : "PD";

        return {

            columns: [

                {
                    width: '*',
                    stack: [
                        NineGazeCard(leftTitle, leftObj, measuredUnit)
                    ]
                },

                {
                    width: 8,
                    text: ""
                },

                {
                    width: '*',
                    stack: [
                        NineGazeCard(middleTitle, middleObj, measuredUnit)
                    ]
                },

                {
                    width: 8,
                    text: ""
                },

                {
                    width: '*',
                    stack: [
                        NineGazeCard(rightTitle, rightObj, measuredUnit)
                    ]
                }

            ]

        };

    }


