    function extractODOSPairs(data) {
        var pairs = [];
        var visited = {};

        angular.forEach(data, function (value, key) {
            if (typeof key === 'string' && key.indexOf('OD') === 0 && !visited[key]) {
                var base = key.substring(2);
                var odKey = 'OD' + base;
                var osKey = 'OS' + base;

                if (data.hasOwnProperty(osKey)) {
                    var obj = {};
                    obj[odKey] = data[odKey];
                    obj[osKey] = data[osKey];

                    pairs.push(obj);
                    visited[odKey] = true;
                    visited[osKey] = true;
                }
            }
        });
        ['ICGFindingArray', 'FundusFindingArray', 'MacularFindingArray', 'ONFindingArray', 'FAFindingArray', 'OtherFindingArray'].forEach(function (arrayName) {
            var arr = data[arrayName];
            if (!Array.isArray(arr) || arr.length === 0) return;

            var odValues = [];
            var osValues = [];

            arr.forEach(function (item) {
                if (item.DeleteInd !== 'N') return;
                if (item.OrganId === 1) odValues.push(item.FindingValue);
                else if (item.OrganId === 2) osValues.push(item.FindingValue);
            });

            if (odValues.length || osValues.length) {
                var baseName = arrayName.replace('Array', '');
                let findingName = baseName.replace(/(.*)(Finding)/, '$1 $2');
                var obj = {};
                if (odValues.length) obj['OD' + findingName] = odValues.join(', ');
                if (osValues.length) obj['OS' + findingName] = osValues.join(', ');
                pairs.push(obj);
            }
        });

        return pairs;
    }
    function generateFindingsODOSTable(data) {
        var hFont = 10;
        const tableBody = [
            [
                { text: '', bold: true },
                { text: 'OD', color: "black", fontSize: hFont, bold: true },
                { text: 'OS', color: "black", fontSize: hFont, bold: true }
            ]
        ];
        data.forEach(pair => {
            const keys = Object.keys(pair);
            const odKey = keys.find(k => k.startsWith("OD"));
            const osKey = keys.find(k => k.startsWith("OS"));

            const odVal = pair[odKey];
            const osVal = pair[osKey];

            if (odVal || osVal) {
                const fieldName = odKey.replace('OD', '');
                tableBody.push([
                    { text: fieldName, color: "black", fontSize: 9, bold: false },
                    { text: odVal || '', color: "black", fontSize: 9, bold: false },
                    { text: osVal || '', color: "black", fontSize: 9, bold: false }
                ]);

            }
        });
        return {
            style: 'tableStyle',
            table: {
                headerRows: 1,
                widths: ['30%', '35%', '35%'],
                body: tableBody
            },
            layout: {
                hLineWidth: function () { return 0.5; },
                vLineWidth: function () { return 0.5; },
                hLineColor: function () { return '#cccccc'; },
                vLineColor: function () { return '#cccccc'; },
                paddingLeft: function () { return 4; },
                paddingRight: function () { return 4; },
                paddingTop: function () { return 2; },
                paddingBottom: function () { return 2; }
            }
        };
    }
