    function getSuperBillData(Object) {
        var hFont = 10;
        var bodyItem = [];
        if (Object.length == 0) {
            return;
        }
        var SuperBillItems = [];
        var SuperBillArray = [];
        if (Object.length > 0) {
            var Array = [];
            Array.push({ text: 'Suggested Procedure', fontSize: 9, alignment: 'left', color: "black", bold: true },
                { text: 'Eye', fontSize: hFont, alignment: 'center', color: "black", bold: true },
                { text: "Units", fontSize: hFont, alignment: 'center', color: "black", bold: true },
                { text: 'Modifier', fontSize: hFont, alignment: 'center', color: "black", bold: true },

            );
            SuperBillItems.push(Array);

            angular.forEach(Object, function (mitem, index) {
                mitem.ProcedureCode = mitem.ProcedureCode || '';
                var Organ = '';
                if (mitem.OrganId == 1) {
                    Organ = 'OD';
                }
                if (mitem.OrganId == 2) {
                    Organ = 'OS';
                }
                if (mitem.OrganId == 3) {
                    Organ = 'OU';
                }
                if (mitem.OrganId == 4) {
                    Organ = 'General';
                }

                var Modifier = '';
                if (mitem.Modifiers.length > 0) {
                    angular.forEach(mitem.Modifiers, function (item, index) {
                        if (Modifier == '') {
                            Modifier = item.ModifierName;
                        } else {
                            Modifier = Modifier + ',' + item.ModifierName;
                        }
                    });
                }

                var D1 = [];
                D1.push({ text: mitem.ProcedureCode + ' - ' + mitem.ProcedureName, fontSize: 9, alignment: 'left', color: "black", bold: false },
                    { text: Organ, fontSize: hFont, alignment: 'center', color: "black", bold: false },
                    { text: mitem.Quantity, fontSize: hFont, alignment: 'center', color: "black", bold: false },
                    { text: Modifier, fontSize: hFont, alignment: 'center', color: "black", bold: false },

                );

                //var Remarks = [{
                //    text: [
                //        { text: 'Notes - ', color: "black", fontSize: 9, bold: true },
                //        { text: mitem.Remarks, color: "black", fontSize: 9, bold: false },
                //    ], colSpan: 5, fontSize: 9, alignment: 'left', color: "black", bold: true
                //}, {}, {}, {}, {},];
                //SuperBillItems.push(Remarks);
                SuperBillItems.push(D1);

                mitem.DiagnosisArray = mitem.DiagnosisArray || [];

                if (mitem.DiagnosisArray.length > 0) {
                    angular.forEach(mitem.DiagnosisArray, function (item, index) {
                        var D2 = [];
                        D2.push({
                            text: [
                                { text: item.ICD10CODE + ' - ', color: "black", fontSize: 9, alignment: 'left', bold: false },
                                { text: item.DiagnosisName, color: "black", fontSize: 9, alignment: 'left', bold: false },
                            ], colSpan: 4
                        }, {}, {}, {})
                        SuperBillItems.push(D2);
                    });

                }

            });
        }
        var A1 = [];
        A1.push({ text: "Super Bill", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'center', bold: false, margin: [0, 5, 0, 0], border: [false, true, true, true] }, {
            table: {
                widths: [250, 40, 40, '*'],
                body: SuperBillItems,
            }, layout: 'noBorders'
        });
        SuperBillArray.push(A1);
        var SuperBilltable = {
            table: {
                widths: [80, '*'],
                body: SuperBillArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        bodyItem.push(SuperBilltable);
        return bodyItem;
    }
