    function getPreSurgeryTableForASC(Object) {
        var hFont = 10;
        if (Object.length == 0) {
            return;
        }
        var Prescriptiondetails = [];
        var PrescriptiondetailsArray = [];
        if (Object.length > 0) {
            angular.forEach(Object, function (mitem) {
                if (mitem.PrescriptionDetails.length > 0) {
                    angular.forEach(mitem.PrescriptionDetails, function (item, index) {
                        var ind = (index + 1) + '. ';
                        var M1 = [];
                        M1.push({ text: ind + item.MedicationName, alignment: 'left', color: "black", fontSize: hFont, bold: true, })
                        Prescriptiondetails.push(M1);
                        var M2 = [];
                        M2.push({ text: item.Action + ' ' + item.Dose + ' ' + item.DoseUnit + ' ' + item.Route + ' ' + item.Frequency + ' ' + item.DoseOther + ' ' + item.DaysSupply, alignment: 'left', color: "black", fontSize: hFont, bold: false, })
                        Prescriptiondetails.push(M2);
                        if (item.PatientInstructions !== '' && item.PatientInstructions !== null) {
                            var M3 = [];
                            M3.push({
                                text: [
                                    { text: "Medication Instructions - ", alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                                    { text: item.PatientInstructions, alignment: 'left', color: "black", fontSize: hFont, bold: false, }
                                ]
                            })
                            Prescriptiondetails.push(M3);
                        }
                    });
                }
            });
        }

        var A1 = [];
        A1.push({ text: "Pre Surgery Medications", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right', border: [false, true, true, true] }, {
            table: {
                widths: ['*'],
                body: Prescriptiondetails,
            }, layout: 'noBorders'
        });
        PrescriptiondetailsArray.push(A1);

        var PrescriptionTable = {
            table: {
                widths: [100, '*'],
                body: PrescriptiondetailsArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        return PrescriptionTable;
    }
    function getLabInvestigationsForASC(Object) {
        var hFont = 10;
        if (Object.length == 0) {
            return;
        }
        var LabInvestigationsdetails = [];
        var LabInvestigationsArray = [];
        if (Object.length > 0) {
            angular.forEach(Object, function (item, index) {
                var SurgeryOrgan = '';
                if (item.OrganId == 1) {
                    SurgeryOrgan = 'OD';
                } else if (item.OrganId == 2) {
                    SurgeryOrgan = 'OS';
                } else if (item.OrganId == 3) {
                    SurgeryOrgan = 'OU';
                } else {
                    SurgeryOrgan = '';
                };
                if (item.LocationId == 2) {
                    SurgeryOrgan = 'General';
                }
                var DurationTypeName = "";
                if (item.Duration !== 0 || item.DurationType == 'SB') {
                    DurationTypeName = item.DurationType === "Y" ? "Years(s)" : (item.DurationType === "M" ? "Month(s)" : (item.DurationType === "D" ? "Day(s)" : (item.DurationType === "W" ? "Week(s)" : (item.DurationType === "C" ? "To Be continued" : (item.DurationType === "L" ? "Life Time" : (item.DurationType === 'SB' ? 'Since Birth' : ""))))));
                }
                var DurationDays = '';
                var String1 = '';
                if (item.Duration !== 0) {
                    DurationDays = item.Duration;
                    String1 = 'Scheduled For';
                }
                var DurationDate = '';
                var String2 = '';
                if (item.DurationDate !== '' && item.DurationDate !== null) {
                    DurationDate = $filter("date")(item.DurationDate, "MM-dd-yyyy");
                    String2 = 'Scheduled On';
                }
                var ind = (index + 1) + '. ';
                var M1 = [];
                item.ProcedureCode = item.ProcedureCode || '';
                M1.push({ text: ind + ' (' + SurgeryOrgan + ' )' + item.ProcedureCode + ' | ' + item.InvestigationName, alignment: 'left', color: "black", fontSize: hFont, bold: true, })
                LabInvestigationsdetails.push(M1);
                var M2 = [];
                M2.push({ text: String1 + String2 + ' ' + DurationDate + DurationDays + ' ' + DurationTypeName, alignment: 'left', color: "black", fontSize: hFont, bold: false, })
                LabInvestigationsdetails.push(M2);
                if (item.InvestigationNotes !== '' && item.InvestigationNotes !== null) {
                    var M3 = [];
                    M3.push({
                        text: [
                            { text: "Notes - ", alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                            { text: item.InvestigationNotes, alignment: 'left', color: "black", fontSize: hFont, bold: false, }
                        ]
                    })
                    LabInvestigationsdetails.push(M3);
                }
            });
        }

        var A1 = [];
        A1.push({ text: "Lab/Investigations", fillColor: "#F1F1F1", fontSize: 10, alignment: 'right', border: [false, true, true, true] }, {
            table: {
                widths: ['*'],
                body: LabInvestigationsdetails,
            }, layout: 'noBorders'
        });
        LabInvestigationsArray.push(A1);

        var PrescriptionTable = {
            table: {
                widths: [100, '*'],
                body: LabInvestigationsArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        return PrescriptionTable;
    }
