    /* Admit print - Consent Forms (same columns as the Consent Forms grid on the Admit screen) */
    function getAdmitConsentSignatureStatus(consent) {
        var roles = [
            { label: 'Patient', required: consent.IsPatientSignRequired, css: consent.PatientClass },
            { label: 'Doctor', required: consent.IsDoctorSignRequired, css: consent.ProviderClass },
            { label: 'Staff', required: consent.IsStaffSignRequired, css: consent.StaffClass },
            { label: 'Anesthesist', required: consent.IsAnesthesistSignRequired, css: consent.AnesthesistClass },
            { label: 'Counselor', required: consent.IsCounselorSignRequired, css: consent.CounselorClass },
            { label: 'Guardian', required: consent.IsGuardianSignRequired, css: consent.GaurdianClass }
        ];
        var parts = [];
        angular.forEach(roles, function (role) {
            if (role.required) {
                parts.push(role.label + ': ' + (role.css === 'complete' ? 'Signed' : 'Pending'));
            }
        });
        return parts.join(', ');
    }

    function getAdmitConsentFormsTable(consents) {
        var bodyItem = [];
        bodyItem.push([{ text: 'Consent Forms', alignment: 'left', bold: true, fontSize: 10, fillColor: '#d3d3d8', colSpan: 5 }, {}, {}, {}, {}]);
        bodyItem.push([
            { text: 'S.No', bold: true, fontSize: 9, fillColor: '#F2F2F2' },
            { text: 'Document Name', bold: true, fontSize: 9, fillColor: '#F2F2F2' },
            { text: 'Document Type', bold: true, fontSize: 9, fillColor: '#F2F2F2' },
            { text: 'Signature Status', bold: true, fontSize: 9, fillColor: '#F2F2F2' },
            { text: 'Patient Signed Date Time', bold: true, fontSize: 9, fillColor: '#F2F2F2' }
        ]);
        angular.forEach(consents, function (consent, index) {
            var documentType = (consent.ConsentTypeName || '') + (consent.IsSignRequiredForEachVisit ? ' (Each Visit)' : '');
            bodyItem.push([
                { text: String(index + 1), fontSize: 9 },
                { text: consent.ConsentFormName || '', fontSize: 9, bold: true },
                { text: documentType, fontSize: 9 },
                { text: getAdmitConsentSignatureStatus(consent), fontSize: 9 },
                { text: consent.PatientSignedDateTime || '', fontSize: 9 }
            ]);
        });
        return {
            margin: [0, 0, 0, 5],
            table: {
                headerRows: 2,
                widths: [30, '*', 90, 150, 90],
                body: bodyItem
            },
            layout: {
                hLineWidth: function () { return 0.5; },
                vLineWidth: function () { return 0.5; },
                hLineColor: function () { return 'gray'; },
                vLineColor: function () { return 'gray'; }
            }
        };
    }

