    function getIntraOpClassificationCasesData(Cleansed, CleanContaminated, Contaminated, Dirty) {
        var hFont = 9;
        var Casesdetails = [];
        var CasesArray = [];
        if (Cleansed == true && CleanContaminated == true && Contaminated == true && Dirty == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'I.Clean , II.Clean/Contaminated, III.Contaminated, IV.Dirty ', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else if (Cleansed == true && CleanContaminated == true && Contaminated == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'I.Clean, II.Clean/Contaminated, III.Contaminated', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else if (Cleansed == true && CleanContaminated == true && Dirty == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'I.Clean, II.Clean/Contaminated, IV.Dirty', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else if (CleanContaminated == true && Contaminated == true && Dirty == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'II.Clean/Contaminated, III.Contaminated , IV.Dirty', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else if (Cleansed == true && CleanContaminated == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'I.Clean, II.Clean/Contaminated', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else if (Cleansed == true && Contaminated == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'I.Clean, III.Contaminated', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else if (CleanContaminated == true && Contaminated == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'II.Clean/Contaminated, III.Contaminated', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else if (CleanContaminated == true && Dirty == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'II.Clean/Contaminated , IV.Dirty', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else if (Contaminated == true && Dirty == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'III.Contaminated , IV.Dirty', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else if (Dirty == true && Cleansed == true) {
            var D1 = [];
            D1.push({
                text: [{ text: 'IV.Dirty, I.Clean', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
            })
            Casesdetails.push(D1);
        } else {
            if (Cleansed == true) {
                var D1 = [];
                D1.push({
                    text: [{ text: 'I.Clean', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
                })
                Casesdetails.push(D1);
            }
            if (CleanContaminated == true) {
                var D1 = [];
                D1.push({
                    text: [{ text: 'II.Clean/Contaminated', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
                })
                Casesdetails.push(D1);
            }
            if (Contaminated == true) {
                var D1 = [];
                D1.push({
                    text: [{ text: 'III.Contaminated', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
                })
                Casesdetails.push(D1);
            }
            if (Dirty == true) {
                var D1 = [];
                D1.push({
                    text: [{ text: 'IV.Dirty', alignment: 'left', color: "black", fontSize: hFont, bold: false }]
                })
                Casesdetails.push(D1);
            }
        }

        var A1 = [];
        A1.push({ text: "Wound Classification", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right' }, {
            table: {
                widths: ['*'],
                body: Casesdetails,
            }, layout: 'noBorders'
        });
        CasesArray.push(A1);

        var PrescriptionTable = {
            table: {
                widths: [100, '*'],
                body: CasesArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        return PrescriptionTable;
    }
