    function getIntraOpActionsInTimeOutTime(obj) {
        var bodyItem = [];
        var hfont = 9;

        //Hall Entrance Start and End Times
        let HallEntranceTimesArary = [];
        let tempHallEntranceArray = [];
        if (obj.SurgeryTimes.HallEntranceStartTime != "" || obj.SurgeryTimes.HallEntranceEndTime != "") {
            tempHallEntranceArray.push({ text: 'O.R. Entrance : ', alignment: 'left', bold: true, fontSize: hfont });
        }
        if (obj.SurgeryTimes.HallEntranceStartTime != "") {
            tempHallEntranceArray.push({ text: 'Start Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempHallEntranceArray.push({ text: obj.SurgeryTimes.HallEntranceStartTime + '    ', alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.SurgeryTimes.HallEntranceEndTime != "") {
            tempHallEntranceArray.push({ text: 'End Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempHallEntranceArray.push({ text: obj.SurgeryTimes.HallEntranceEndTime, alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.SurgeryTimes.HallEntranceStartTime != "" || obj.SurgeryTimes.HallEntranceEndTime != "") {
            HallEntranceTimesArary.push({ text: tempHallEntranceArray });
            bodyItem.push(HallEntranceTimesArary);
        }

        // Anesthesia start and end times
        let AnesthesiaTimesArary = [];
        let tempAnesthesiaArray = [];
        if (obj.SurgeryTimes.AnesthesiaStartTime != "" || obj.SurgeryTimes.AnesthesiaEndTime != "") {
            tempAnesthesiaArray.push({ text: 'Anesthesia     : ', alignment: 'left', bold: true, fontSize: hfont });
        }
        if (obj.SurgeryTimes.AnesthesiaStartTime != "") {
            tempAnesthesiaArray.push({ text: 'Start Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempAnesthesiaArray.push({ text: obj.SurgeryTimes.AnesthesiaStartTime + '    ', alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.SurgeryTimes.AnesthesiaEndTime != "") {
            tempAnesthesiaArray.push({ text: 'End Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempAnesthesiaArray.push({ text: obj.SurgeryTimes.AnesthesiaEndTime, alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.SurgeryTimes.AnesthesiaStartTime != "" || obj.SurgeryTimes.AnesthesiaEndTime != "") {
            AnesthesiaTimesArary.push({ text: tempAnesthesiaArray });
            bodyItem.push(AnesthesiaTimesArary);
        }

        // surgery start and end times
        let SurgeryTimesArary = [];
        let tempArray = [];
        if (obj.SurgeryTimes.SurgeryStartTime != "" || obj.SurgeryTimes.SurgeryEndTime != "") {
            tempArray.push({ text: 'Surgery           : ', alignment: 'left', bold: true, fontSize: hfont });
        }
        if (obj.SurgeryTimes.SurgeryStartTime != "") {
            tempArray.push({ text: 'Start Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempArray.push({ text: obj.SurgeryTimes.SurgeryStartTime + '    ', alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.SurgeryTimes.SurgeryEndTime != "") {
            tempArray.push({ text: 'End Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempArray.push({ text: obj.SurgeryTimes.SurgeryEndTime, alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.SurgeryTimes.SurgeryStartTime != "" || obj.SurgeryTimes.SurgeryEndTime != "") {
            SurgeryTimesArary.push({ text: tempArray });
            bodyItem.push(SurgeryTimesArary);
        }


        // Recovery start and end times
        let RecoveryTimesArary = [];
        let tempRecoveryArray = [];
        if (obj.SurgeryTimes.RecoveryStartTime != "" || obj.SurgeryTimes.RecoveryStopTime != "") {
            tempRecoveryArray.push({ text: 'Recovery        : ', alignment: 'left', bold: true, fontSize: hfont });
        }
        if (obj.SurgeryTimes.RecoveryStartTime != "") {
            tempRecoveryArray.push({ text: 'Start Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempRecoveryArray.push({ text: obj.SurgeryTimes.RecoveryStartTime + '     ', alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.SurgeryTimes.RecoveryStopTime != "") {
            tempRecoveryArray.push({ text: 'End Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempRecoveryArray.push({ text: obj.SurgeryTimes.RecoveryStopTime, alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.SurgeryTimes.RecoveryStartTime != "" || obj.SurgeryTimes.RecoveryStopTime != "") {
            RecoveryTimesArary.push({ text: tempRecoveryArray });
            bodyItem.push(RecoveryTimesArary);
        }

        var PreSurgeryArray = [];
        var InTimeValue = '';
        var OutTimeValue = '';

        if (obj.InTime !== '') {
            InTimeValue = 'InTime : ';
        }
        if (obj.OutTime !== '') {
            OutTimeValue = 'OutTime : ';
        }

        PreSurgeryArray.push({
            text: [
                { text: InTimeValue, alignment: 'left', bold: true, fontSize: hfont, },
                { text: obj.InTime + '    ', alignment: 'left', bold: false, fontSize: hfont, },
                { text: OutTimeValue, alignment: 'left', bold: true, fontSize: hfont, },
                { text: obj.OutTime + '    ', alignment: 'left', bold: false, fontSize: hfont, },

            ]
        });
        bodyItem.push(PreSurgeryArray);

        var PreSurgeryTable = {
            table: {
                widths: '*',
                body: bodyItem
            },
            layout: 'noBorders'
        };
        return PreSurgeryTable;
    }
