    function getOperativeNoteAddendumData(Obj) {
        var hFont = 9;
        var AddendumArray = [];
        angular.forEach(Obj, function (item, index) {
            var bodyItem = [];
            var AddendumDate = item.CreatedDt ? $filter('date')(item.CreatedDt, "MM-dd-yyyy") : '';
            var AddendumTime = item.CreatedDt ? $filter('date')(item.CreatedDt, "hh:mm a") : '';
            var AddendumSignedDate = item.SignedDate || item.CreatedDt;
            var SignedDate = AddendumSignedDate ? $filter('date')(AddendumSignedDate, "MM-dd-yyyy hh:mm a") : '';
            var SignedByLicense = item.LicenseNumber ? ' Lic: ' + item.LicenseNumber + ',' : '';

            bodyItem.push([{ text: 'Addendum ' + (index + 1), alignment: 'left', bold: true, fontSize: 10, fillColor: '#d3d3d8' }]);
            bodyItem.push([{ text: [{ text: 'Date : ', bold: true }, { text: AddendumDate + '   ' }, { text: 'Time : ', bold: true }, { text: AddendumTime + '   ' }, { text: 'Authored by : ', bold: true }, { text: (item.AuthoredByUserName || '') + ' ' + (item.AuthoredBySuffixName || '') }], alignment: 'left', color: "black", fontSize: hFont }]);
            bodyItem.push([{ text: [{ text: 'Reason : ', bold: true }, { text: item.AddendumReasonName || '' }], alignment: 'left', color: "black", fontSize: hFont }]);
            bodyItem.push([{ text: [{ text: 'Text : ', bold: true }, { text: item.AddendumText || '' }], alignment: 'left', color: "black", fontSize: hFont }]);
            bodyItem.push([{ text: 'Original note remains unaltered and is to be read in conjunction with this addendum.', bold: true, alignment: 'left', color: "black", fontSize: hFont }]);
            bodyItem.push([{ text: [{ text: 'Electronically Signed By : ', bold: true }, { text: (item.SignOffUserName || '') + ' ' + (item.SuffixName || '') + ',' + SignedByLicense + '  ' + SignedDate }], alignment: 'left', color: "black", fontSize: hFont }]);

            AddendumArray.push({
                margin: [0, 5, 0, 5],
                unbreakable: true,
                table: {
                    widths: ['*'],
                    body: bodyItem
                },
                layout: 'noBorders'
            });
        });
        return AddendumArray;
    }
