    function generateTextSection(headerText, contentText, fontSize) {
        if (!contentText || contentText.trim() === '') return [];

        const formattedText = contentText;

        const headerTable = {
            table: {
                widths: ['*'],
                body: [
                    [
                        {
                            text: headerText,
                            alignment: 'left',
                            color: 'black',
                            fontSize: 10,
                            bold: true,
                            border: [false, false, false, true],
                            margin: [0, 0, 0, 0]
                        }
                    ]
                ]
            },
            layout: {
                hLineWidth: function (i, node) {
                    return 0.5;
                },
                vLineWidth: function () {
                    return 0;
                },
                hLineColor: function () {
                    return 'gray';
                },
                vLineColor: function () {
                    return '';
                }
            }
        };

        const contentTable = {
            table: {
                widths: ['*'],
                body: [
                    [
                        {
                            text: formattedText,
                            alignment: 'left',
                            color: 'black',
                            fontSize: fontSize,
                            bold: false
                        }
                    ]
                ]
            },
            layout: 'noBorders'
        };

        return [headerTable, contentTable];
    }

