    function getPreOpCallDetailData(obj) {
        var hFont = 9;
        var bodyItem = [];

        if (obj.length == 0) {
            return;
        }

        var PreopVitalArray = [];
        var PreopVitalItem = [];


        angular.forEach(obj, function (item) {


            let IsNoResponse = '';
            var preopinstructions = '';
            if (item.IsNoResponse) {
                IsNoResponse = 'No Response';
            } else {
                if (item.IsConnectedWithPatient) {
                    preopinstructions = "Connected with Patient, " || "";
                }
                if (item.IsConnectedWithFamilyOrFriend) {
                    preopinstructions += "Connected with Family/Friend, " || "";
                }
                if (item.IsLeftMsgWithFamilyOrFriend) {
                    preopinstructions += "Left Message With family/friends, " || "";
                }
                if (item.IsLeftMsgWithPatient) {
                    preopinstructions += "Left Message With Patient, " || "";
                }
                if (item.IsConnectedWithPatient || item.IsConnectedWithFamilyOrFriend || item.IsLeftMsgWithFamilyOrFriend || item.IsLeftMsgWithPatient) {
                    preopinstructions += "and shared instructions about " || "";
                }
                if (item.IsArrivalTimeShared) {
                    preopinstructions += "arrival Time, " || "";
                }
                if (item.IsAccompanyShared) {
                    preopinstructions += "accompany, " || "";
                }
                if (item.IsDrinkPlentyWaterShared) {
                    preopinstructions += "Drink plenty Of Water, " || "";
                }
                if (item.IsNpoAfterMidnightShared) {
                    preopinstructions += "Npo After Midnight, " || "";
                }
                if (item.IsTakeBpHeartMedShared) {
                    preopinstructions += "TakeBp/Heart Medications, " || "";
                }
                if (item.IsDoNotTakeBpMedShared) {
                    preopinstructions += "Do Not Take Diabetic Medications, " || "";
                }
                if (item.IsNoMakeupJewelMoistShared) {
                    preopinstructions += "No Makeup and Jewelry/Moysturisers, " || "";
                }
                if (item.IsCoPay) {
                    preopinstructions += "Co-Pay, " || "";
                }

                preopinstructions = preopinstructions.replace(/,\s*$/, "");

                IsNoResponse = preopinstructions;
            }


            let Line1 = [];
            Line1.push(
                {
                    text: [{ text: 'Contacted : ', fontSize: 9, alignment: 'left', color: "black", bold: true, border: [false, false, false, false] },
                    { text: item.ContactType, fontSize: 9, alignment: 'left', color: "black", bold: false, border: [false, false, false, false] }
                    ]
                },
                {
                    text: [{ text: 'Date : ', fontSize: 9, alignment: 'left', color: "black", bold: true, border: [false, false, false, false] },
                    { text: item.ContactStartDate, fontSize: 9, alignment: 'left', color: "black", bold: false, border: [false, false, false, false] }
                    ]
                },
                {
                    text: [{ text: 'Time : ', fontSize: 9, alignment: 'left', color: "black", bold: true, border: [false, false, false, false] },
                    { text: item.ContactStartTime, fontSize: 9, alignment: 'left', color: "black", bold: false, border: [false, false, false, false] }
                    ]
                },
            );
            PreopVitalItem.push(Line1);

            if (IsNoResponse != '') {
                let Line2 = [];
                Line2.push(
                    { text: IsNoResponse, fontSize: 9, colSpan: 3, alignment: 'left', color: "black", bold: true, border: [false, false, false, false] }, {}, {},
                );
                PreopVitalItem.push(Line2);
            }
            var startdropsdate = '';
            var startdropstime = '';
            var eyedropnote = '';

            if (item.DropStartDate !== '') {
                startdropsdate = 'Start Drops Date : ';
            }
            if (item.DropsStartTime !== '') {
                startdropstime = 'Start Drops Time : ';
            }
            if (item.CoPayNotes !== '') {
                eyedropnote = 'Eye Drop Note : ';
            }

            var DropStartDate = $filter('date')(item.DropStartDate, "MM-dd-yyyy") || "";
            var DropsStartTime = $filter('date')(item.DropsStartTime, "hh:mm a") || "";

            let Line3 = [];
            if (item.DropStartDate != '' || item.DropsStartTime != '' || item.CoPayNotes != '') {
                Line3.push(
                    { text: startdropsdate + DropStartDate, fontSize: 9, alignment: 'left', color: "black", bold: false, border: [false, false, false, false], margin: [0, 0, 5, 0] }, // Added margin to the right
                    { text: startdropstime + DropsStartTime, fontSize: 9, alignment: 'left', color: "black", bold: false, border: [false, false, false, false], margin: [0, 0, 5, 0] }, // Added margin to the right
                    { text: eyedropnote + item.CoPayNotes, fontSize: 9, alignment: 'left', color: "black", bold: false, border: [false, false, false, false] },
                );
                PreopVitalItem.push(Line3);
            }

            if (item.Remarks != '') {
                let Line4 = [];
                Line4.push(
                    { text: 'Notes : ' + item.Remarks, fontSize: 9, colSpan: 3, alignment: 'left', color: "black", bold: false, border: [false, false, false, false] }, {}, {},
                );
                PreopVitalItem.push(Line4);
            }

        })


        var A1 = [];
        A1.push({ text: "Pre-Op Call", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right', margin: [0, 5, 0, 0], border: [false, true, true, true] }, {
            table: {
                widths: [150, 150, 100, '*'],
                body: PreopVitalItem,
            }, layout: 'noBorders'
        });
        PreopVitalArray.push(A1);

        var CycloplegicRefractiontable = {
            table: {
                widths: [100, '*'],
                body: PreopVitalArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        bodyItem.push(CycloplegicRefractiontable);
        return bodyItem;
    }

