    function getDietMedicationsData(Object, ChecklistNotes) {
        var hFont = 9;
        var bodyItem = [];
        var ChecklistNotesItem = [];


        ChecklistNotes = ChecklistNotes || '';

        let DietMedicationsData = $filter('filter')(Object, { 'IsChecked': true }, true) || [];


        if (DietMedicationsData.length == 0) {
            return;
        }
        var PreopVitalArray = [];
        var PreopVitalItem = [];

        let tempArray = Object
            .filter(item =>
                item.CheckListCategoryId === 25
            )
            .sort((a, b) => a.OrgOrderBy - b.OrgOrderBy);

        if (tempArray.length > 0) {
            if (tempArray.length > 0) {
                angular.forEach(tempArray, function (item) {
                    var ChecklistDate = '';
                    var ChecklistTime = '';
                    if (item.ChecklistDate) {
                        ChecklistDate = $filter("date")(item.ChecklistDate, "MM-dd-yyyy");
                    }
                    if (item.ChecklistTime) {
                        ChecklistTime = $filter("date")(item.ChecklistTime, "hh: mm a");
                    }
                    let Line1 = [];
                    Line1.push(
                        { text: item.CheckListName, fontSize: hFont, alignment: 'left', color: "black", bold: false, },
                        { text: ':', fontSize: hFont, alignment: 'left', color: "black", bold: true, },
                        { text: item.Value, fontSize: hFont, alignment: 'left', color: "black", bold: true, },
                        { text: ChecklistDate + '  ' + ChecklistTime, fontSize: hFont, alignment: 'left', color: "black", bold: true, },
                    );
                    PreopVitalItem.push(Line1);
                    if (item.Remarks) {
                        let Line2 = [];
                        Line2.push({}, {},
                            {
                                text: [{ text: 'Notes : ', fontSize: 9, alignment: 'left', color: "black", bold: false, },
                                { text: item.Remarks, fontSize: 9, alignment: 'left', color: "black", bold: false, },
                                ], colSpan: 2,
                            }, {}
                        );
                        PreopVitalItem.push(Line2);
                    }
                });
            }
            var A1 = [];
            A1.push({ text: "Diet Or Medications Taken", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right', margin: [0, 5, 0, 0], border: [false, true, true, true] }, {
                table: {
                    widths: [200, 5, 60, '*'],
                    body: PreopVitalItem,
                }, layout: 'noBorders'
            });
            PreopVitalArray.push(A1);
        }

        if (ChecklistNotes) {
            ChecklistNotes = ChecklistNotes.replaceAll('<br>', '\n');
            let Line3 = [];
            Line3.push(
                {
                    text: ChecklistNotes, fontSize: 9, alignment: 'left', color: "black", bold: false, colSpan: 4,
                }, {}, {}, {}
            );
            ChecklistNotesItem.push(Line3);
            var A2 = [];
            A2.push({ text: "Notes", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right', margin: [0, 5, 0, 0], border: [false, true, true, true] }, {
                table: {
                    widths: [200, 5, 60, '*'],
                    body: ChecklistNotesItem,
                }, layout: 'noBorders'
            });
            PreopVitalArray.push(A2);
        }

        var CycloplegicRefractiontable = {
            table: {
                widths: [100, '*'],
                body: PreopVitalArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        bodyItem.push(CycloplegicRefractiontable);
        return bodyItem;
    }
