    function getDilationMedicationsData1(Object, ODPupilSize, OSPupilSize, DilationReviewName, DilationMedicationsNotes, ModifiedDate) {
        var hFont = 9;
        if (Object.length == 0) {
            return;
        }
        var Prescriptiondetails = [];
        var PrescriptiondetailsArray = [];
        if (Object.length > 0) {
            angular.forEach(Object, function (item, index) {
                //var ind = (index + 1) + '. ';
                var ind = '';
                var dosage = '';
                let Dosageandtime = '';
                if (item.DropTimings.length > 0) {
                    angular.forEach(item.DropTimings, function (Bitem, index) {
                        if (Bitem.MedicationTime !== '') {
                            ind = ' at ';
                        }
                        if (Bitem.MedicationDosage !== '') {
                            dosage = ' D ';
                        }
                        Dosageandtime += "," + Bitem.MedicationDosage + ind + Bitem.MedicationTime; //dosage
                    });
                    if (Dosageandtime.charAt(0) === ",") {
                        Dosageandtime = Dosageandtime.slice(1);
                    }
                }
                var M1 = [];
                M1.push({ text: item.MedicationName, alignment: 'left', color: "black", fontSize: 9, bold: true, },
                    { text: Dosageandtime, alignment: 'left', color: "black", fontSize: 9, bold: false, })
                Prescriptiondetails.push(M1);
            });
        }
        if (ODPupilSize !== '' || OSPupilSize !== '') {
            var ODPupilsizevalue = '';
            var OSPupilsizevalue = '';
            if (ODPupilSize !== '') {
                ODPupilsizevalue = 'OD - ' + ODPupilSize + ' mm';
            }
            if (OSPupilSize !== '') {
                OSPupilsizevalue = 'OS - ' + OSPupilSize + ' mm';
            }
            var P1 = [];
            P1.push({
                text: [{ text: 'Pupil Size : ', alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                { text: ODPupilsizevalue + '      ', alignment: 'left', color: "black", fontSize: hFont, bold: false, },
                { text: OSPupilsizevalue, alignment: 'left', color: "black", fontSize: hFont, bold: false, },
                ], colSpan: 2
            }, {},
            )
            Prescriptiondetails.push(P1);
        }
        if (DilationReviewName !== '' && DilationReviewName !== null) {
            var ModifiedDt = '';
            var ModifiedDt = ModifiedDate;
            var P2 = [];
            P2.push({
                text: [{ text: 'Given By : ', alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                { text: DilationReviewName + ' ' + ModifiedDt, alignment: 'left', color: "black", fontSize: hFont, bold: false, },
                ], colSpan: 2
            }, {}
            )
            Prescriptiondetails.push(P2);
        }
        if (DilationMedicationsNotes !== '' && DilationMedicationsNotes !== null) {
            var P2 = [];
            P2.push({
                text: [{ text: 'Notes : ', alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                { text: DilationMedicationsNotes, alignment: 'left', color: "black", fontSize: hFont, bold: false, },
                ], colSpan: 2
            }, {}
            )
            Prescriptiondetails.push(P2);
        }
        var A1 = [];
        A1.push({
            table: {
                widths: [250, '*'],
                body: Prescriptiondetails,
            }, layout: 'noBorders'
        });
        PrescriptiondetailsArray.push(A1);

        var PrescriptionTable = {
            table: {
                widths: ['*'],
                body: PrescriptiondetailsArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        return PrescriptionTable;
    }
    function getPreOpMedicationsData1(Object, IsVeinOpened, IsDiabetes, MedicationReviewName, MedicationRemarks, ModifiedDate, DiabetesTimings) {
        var hFont = 9;
        //if (Object.length == 0) {
        //    return;
        //}
        var Prescriptiondetails = [];
        var PrescriptiondetailsArray = [];
        var isVeinOpened = '';
        var isDiabetes = '';
        if (IsVeinOpened !== '') {
            if (IsVeinOpened == true) {
                isVeinOpened = "Is Vein Opened : Yes";
            } else {
                isVeinOpened = "Is Vein Opened : No";
            }
        }
        if (IsDiabetes !== '') {
            if (IsDiabetes == true) {
                isDiabetes = "Diabetes : Yes";
            } else {
                isDiabetes = "Diabetes : No";
            }
        }

        //var Result = '';
        //DiabetesResult = DiabetesResult || '';
        //if (DiabetesResult !== '') {
        //    Result = 'Diabetes Result : '+DiabetesResult+' mg/dL';
        //} else {
        //    Result = "";
        //}
        //var Time = '';
        //DiabetesTime = DiabetesTime || '';
        //if (DiabetesTime !== '') {
        //    Time = 'Time : '+DiabetesTime;
        //} else {
        //    Time = "";
        //}

        var DiabetesArray = [];

        DiabetesArray = DiabetesTimings || [];

        if (isVeinOpened !== '' || isDiabetes !== '' || DiabetesArray.length > 0) {
            var D1 = [];
            D1.push({ text: isVeinOpened + '    ' + isDiabetes + '    ', alignment: 'left', color: "black", fontSize: 9, bold: false, colSpan: 2, margin: [0, 0, 0, 10] }, {})
            Prescriptiondetails.push(D1);


            let Diabetesandtime = '';
            let Ind = '';
            if (DiabetesArray.length > 0) {
                angular.forEach(DiabetesArray, function (item, index) {
                    if (item.DiabetesTime) {
                        Ind = ' at ';
                    }
                    Diabetesandtime += "," + item.DiabetesResult + Ind + item.DiabetesTime;

                    if (Diabetesandtime.charAt(0) === ",") {
                        Diabetesandtime = Diabetesandtime.slice(1);
                    }

                });
                var Z1 = [];
                Z1.push(
                    { text: 'Diabetes Result & Time :', alignment: 'left', color: "black", fontSize: 9, bold: false, },
                    { text: Diabetesandtime, alignment: 'left', color: "black", fontSize: 9, bold: false, })
                Prescriptiondetails.push(Z1);
            }

        }

        if (Object.length > 0) {
            angular.forEach(Object, function (item, index) {
                // var ind = (index + 1) + '. ';
                let ind = '';
                var dosage = '';
                let Dosageandtime = '';
                if (item.DropTimings.length > 0) {
                    angular.forEach(item.DropTimings, function (Bitem, index) {
                        if (Bitem.MedicationTime !== '') {
                            ind = ' at ';
                        }
                        if (Bitem.MedicationDosage !== '') {
                            dosage = ' D ';
                        }
                        Dosageandtime += "," + Bitem.MedicationDosage + ind + Bitem.MedicationTime; //dosage
                    });
                    if (Dosageandtime.charAt(0) === ",") {
                        Dosageandtime = Dosageandtime.slice(1);
                    }
                }
                var M1 = [];
                M1.push({ text: item.MedicationName, alignment: 'left', color: "black", fontSize: 9, bold: true, },
                    { text: Dosageandtime, alignment: 'left', color: "black", fontSize: 9, bold: false, })
                Prescriptiondetails.push(M1);


            });
        }
        if (MedicationReviewName !== '') {
            var M2 = [];
            var ModifiedDt = '';
            var ModifiedDt = ModifiedDate;
            M2.push({
                text: [{ text: 'Given By : ', alignment: 'left', color: "black", fontSize: 9, bold: true, },
                { text: MedicationReviewName + ' ' + ModifiedDt, alignment: 'left', color: "black", fontSize: 9, bold: false, },
                ], colSpan: 2
            }, {})
            Prescriptiondetails.push(M2);
        }
        if (MedicationRemarks !== '') {
            var M3 = [];
            M3.push({
                text: [{ text: 'Notes : ', alignment: 'left', color: "black", fontSize: 9, bold: true, },
                { text: MedicationRemarks, alignment: 'left', color: "black", fontSize: 9, bold: false, },
                ], colSpan: 2
            }, {})
            Prescriptiondetails.push(M3);
        }

        var A1 = [];
        A1.push({
            table: {
                widths: [200, '*'],
                body: Prescriptiondetails,
            }, layout: 'noBorders'
        });
        PrescriptiondetailsArray.push(A1);

        var PrescriptionTable = {
            table: {
                widths: ['*'],
                body: PrescriptiondetailsArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        return PrescriptionTable;
    }
    function getPageBreakTable() {
        var breaktype = 'after';
        var bodyItem = [];
        var PageBreakArray = [];
        PageBreakArray.push({ text: '' });
        bodyItem.push(PageBreakArray);
        var PageBreakTable = {
            table: {
                widths: '*',
                body: bodyItem
            },
            layout: 'noBorders',
            pageBreak: breaktype
        };
        return PageBreakTable;
    }
