    /* Pre-Op Surgeon Orders (MedTypeId 2) saved from the Admit screen, read from a GetASCAdmissionDetails response.
       Returns them in the shape getDilationMedicationsPIP and the Quick Summary use (same rules as the Admit screen):
       active rows only, Standing (1) before Live (2), Given By name / licence resolved, times as "hh:mm AM". */
    this.GetAdmitSurgeonOrdersFromAdmission = function (admissionData, userList) {
        admissionData = admissionData || {};
        userList = userList || [];
        let row = (angular.isArray(admissionData.rows) && admissionData.rows[0]) || {};
        let readValue = function (key) {
            return (admissionData[key] !== undefined && admissionData[key] !== null) ? admissionData[key] : row[key];
        };
        let orders = readValue('OrderDetails') || [];
        if (angular.isString(orders)) {
            try { orders = JSON.parse(orders) || []; } catch (e) { orders = []; }
        }
        if (!angular.isArray(orders)) {
            orders = [];
        }
        let isActiveRow = function (x) { return x && x.DeleteInd !== 'Y'; };
        let findUser = function (id) {
            return id ? (userList.filter(function (u) { return u.DoctorID == id; })[0] || null) : null;
        };
        let formatTime = function (value) {
            if (value === null || value === undefined) {
                return '';
            }
            value = String(value).trim();
            let match = value.match(/(?:^|T|\s)(\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?\s*(AM|PM)?$/i);
            if (!match) {
                return value;
            }
            let hours = Number(match[1]);
            let meridian = match[3] ? match[3].toUpperCase() : '';
            if (!meridian) {
                meridian = hours >= 12 ? 'PM' : 'AM';
                hours = hours % 12 || 12;
            }
            return ('0' + hours).slice(-2) + ':' + match[2] + ' ' + meridian;
        };
        let formatStatus = function (status) {
            let key = String(status || '').replace(/[\s_-]/g, '').toLowerCase();
            return key === 'done' ? 'Done' : (key === 'notdone' ? 'NotDone' : (status || ''));
        };
        let orderTypeOf = function (Mitem) {
            let typeId = Number(Mitem.OrderTypeId) || 0;
            if (!typeId) {
                let typed = (Mitem.DilationMedications || []).concat(Mitem.GeneralOrders || []).filter(function (x) { return Number(x.OrderTypeId) > 0; })[0];
                typeId = typed ? Number(typed.OrderTypeId) : 0;
            }
            if (!typeId && Mitem.OrderTypeName) {
                typeId = /live/i.test(Mitem.OrderTypeName) ? 2 : 1;
            }
            return typeId == 2 ? 2 : 1;
        };

        let surgeonOrders = orders.filter(function (Mitem) {
            if (!isActiveRow(Mitem)) {
                return false;
            }
            if (Mitem.MedTypeId != null && Mitem.MedTypeId !== '') {
                return Mitem.MedTypeId == 2;
            }
            return Mitem.MedTypeName == 'Dilation Medication' || angular.isArray(Mitem.DilationMedications) || angular.isArray(Mitem.AscMedications);
        }).map(function (source) {
            let Mitem = angular.copy(source);
            Mitem.DilationMedications = Mitem.DilationMedications || Mitem.AscMedications || [];
            Mitem.GeneralOrders = Mitem.GeneralOrders || [];
            Mitem.OrderTypeId = orderTypeOf(Mitem);
            Mitem.OrderTypeName = Mitem.OrderTypeId == 2 ? "Live Medications" : "Standing Medications(Pre Surgery)";

            Mitem.DilationMedications = Mitem.DilationMedications.filter(isActiveRow).map(function (item) {
                item.OrderDescription = item.OrderDescription || item.MedicationName || '';
                item.MedicationNotes = item.MedicationNotes || '';
                item.DropTimings = (item.DropTimings || []).filter(isActiveRow).map(function (kitem) {
                    let givenBy = findUser(kitem.GivenBy);
                    kitem.MedicationDosage = kitem.MedicationDosage || '';
                    kitem.MedicationTime = formatTime(kitem.MedicationTime);
                    kitem.GivenByname = kitem.GivenByname || kitem.GivenByName || (givenBy ? givenBy.FullName : '') || '';
                    kitem.LicenseNumber = kitem.LicenseNumber || (givenBy ? givenBy.LicenseNumber : '') || '';
                    kitem.Remarks = kitem.Remarks || '';
                    return kitem;
                });
                return item;
            });

            Mitem.GeneralOrders = Mitem.GeneralOrders.filter(isActiveRow).map(function (gitem) {
                gitem.Status = formatStatus(gitem.Status);
                gitem.MedicationTime = formatTime(gitem.MedicationTime);
                if (!gitem.Status && gitem.MedicationTime) {
                    gitem.Status = 'Done';
                }
                let givenBy = findUser(gitem.GivenBy);
                let isDone = gitem.Status === 'Done';
                gitem.MedicationTime = isDone ? gitem.MedicationTime : '';
                gitem.GivenByname = isDone ? (gitem.GivenByname || gitem.GivenByName || (givenBy ? givenBy.FullName : '') || '') : '';
                gitem.LicenseNumber = isDone ? (gitem.LicenseNumber || (givenBy ? givenBy.LicenseNumber : '') || '') : '';
                return gitem;
            });

            Mitem.IsOrderReviewed = Mitem.IsOrderReviewed === true || Mitem.IsOrderReviewed === 1 || Mitem.IsOrderReviewed === 'true';
            let reviewer = findUser(Mitem.ReviewedBy);
            Mitem.ReviewedByName = Mitem.IsOrderReviewed ? (Mitem.ReviewedByName || (reviewer ? reviewer.FullName : '') || '') : '';
            Mitem.LicenseNumber = Mitem.LicenseNumber || (reviewer ? reviewer.LicenseNumber : '') || '';
            return Mitem;
        }).filter(function (Mitem) {
            return Mitem.DilationMedications.length > 0 || Mitem.GeneralOrders.length > 0;
        }).sort(function (a, b) {
            return a.OrderTypeId - b.OrderTypeId;
        });

        /* Admit Checklist (CheckListCategoryId 17) saved on Admit - NPO time is shown against checklist 243 */
        let checkLists = angular.isArray(row.CheckLists) ? row.CheckLists : [];
        let admitChecklist = checkLists.filter(function (item) {
            return item && item.CheckListCategoryId == 17 && item.DeleteInd !== 'Y';
        }).map(function (source) {
            let item = angular.copy(source);
            item.Time = item.CheckListId == 243 ? (row.NPOTime || '') : '';
            return item;
        });

        return {
            "AdmitChecklist": admitChecklist,
            "OrderDetails": surgeonOrders,
            "ODPupilSize": readValue('ODPupilSize') || '',
            "OSPupilSize": readValue('OSPupilSize') || '',
            "IsSurgeonOrdersTimeChecked": readValue('IsSurgeonOrdersTimeChecked') === true || readValue('IsSurgeonOrdersTimeChecked') === 1
        };
    };

