            var A1 = [];
            A1.push({ text: "Surgeon Operative Notes", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right', margin: [0, 5, 0, 0], border: [false, true, true, true] }, {
                table: {
                    widths: ['*'],
                    body: OperativeNotesItem,
                }, layout: 'noBorders'
            });
