    this.GenerateASCPreopDataPrint = function (obj) {
        var doctorinfo = eHnoteMasterDataService.getUserInfo();
        let printSettingInfo = eHnoteMasterDataService.getPrintSettingSpecific("OT").PageSettings;
        let emptyRow = getEmptyTable();
        let data = printSettings;
        let pageSettings = {
            "marginLeft": 20,
            "marginTop": 100,
            "marginRight": 20,
            "marginBottom": 10
        };
        let headerHeight = 100;
        let footerHeight = 100;
        let docSign = "";
        let isDefaultDocSign = "";
        let content = [];
        contentSetting = setContentSettings();
        if (data !== undefined) {
            pageSettings = data.JsonSetting.pageSettings;
            headerHeight = data.JsonSetting.clinicSettings.headerSettings.dimension.height;
            footerHeight = data.JsonSetting.clinicSettings.footerSettings.dimension.height;
            contentSetting = data.JsonSetting.clinicSettings.contentSettings;
            docSign = data.JsonSetting.clinicSettings.footerSettings.custFootSign;
            isDefaultDocSign = data.JsonSetting.clinicSettings.footerSettings.isFootSignDefault;
            if (printSettingInfo.PageSize === "A4") {
                defaultFontSize = 10;
            } else {
                printPageSize = "A4";
                defaultFontSize = 10;
            }
        }
        //content.push(getHeaderInfoTableForPreOp());
        //var branchName = "";
        //if (doctorinfo.doctordata.UserAddress.length > 0) {
        //    branchName = doctorinfo.doctordata.UserAddress[0].ClinicName;
        //}
        //content.push(getHeaderInfoTableForPreOpWithBranch(branchName));

        content.push(getPatientBranchDetailsTableForASC(obj));
        content.push(getPatientDetailsTable());
        content.push(getPatientDetailsTableForASC(obj));
        content.push(getPatientSurgeryDetailsTable());
        content.push(getPatientSurgeryDetailsTableForASC(obj));

        obj.AirWayData = obj.AirWayData || null;
        if (obj.AirWayData != null) {
            obj.AirWayData.AirIsNormal = obj.AirWayData.AirIsNormal || false;
            obj.AirWayData.AirROMTMS = obj.AirWayData.AirROMTMS || '';
            obj.AirWayData.AirROMNECKAP = obj.AirWayData.AirROMNECKAP || '';
            obj.AirWayData.AirROMNECKLAT = obj.AirWayData.AirROMNECKLAT || '';
            obj.AirWayData.AirClass = obj.AirWayData.AirClass || '';
            obj.AirWayData.Dentition = obj.AirWayData.Dentition || '';
            obj.AirWayData.AirNotes = obj.AirWayData.AirNotes || '';
            obj.AirWayData.DentitionList = obj.AirWayData.DentitionList || [];
        }

        if (obj.VitalsArray.length > 0) {
            let VitalsItems = getVitalData(obj.VitalsArray);
            content.push(getVitalsInfoTableForASC());
            content.push(VitalsItems);
        }
        if (obj.AllergyItems.length > 0 || obj.CurrentEyeMedications.length > 0 || obj.SystemicHistory.length > 0 || obj.SurgicalHistory.length > 0
            || obj.CurrentSystemicMedicationsHistory.length > 0 || obj.SurgicalHistory.length > 0) {
            content.push(getnewROSInfoTable());
        }
        if (obj.AllergyItems.length > 0) {
            var AllergyItems = getAllergyData(obj.AllergyItems);
            content.push(AllergyItems);
        }
        if (obj.SystemicHistory.length > 0) {
            var SystemicHistoryItems = getSystemicHistoryData(obj);
            content.push(SystemicHistoryItems);
        }
        if (obj.SurgicalHistory.length > 0) {
            var SurgicalHistoryItems = getSurgicalHistoryData(obj.SurgicalHistory);
            content.push(SurgicalHistoryItems);
        }
        if (obj.CurrentEyeMedications.length > 0) {
            var CurrentEyeMedicationsItems = getCurrentEyeMedicationsData(obj.CurrentEyeMedications);
            content.push(CurrentEyeMedicationsItems);
        }
        if (obj.CurrentSystemicMedicationsHistory.length > 0) {
            var CurrentSystemicMedicationsItems = getCurrentSystemicMedicationsData(obj.CurrentSystemicMedicationsHistory);
            content.push(CurrentSystemicMedicationsItems);
        }
        if (obj.HandpLabdata.length > 0 || (obj.AirWayData.AirIsNormal !== undefined && (obj.AirWayData.AirIsNormal == true || obj.AirWayData.AirROMTMS !== '' || obj.AirWayData.AirROMNECKAP !== '' || obj.AirWayData.AirROMNECKLAT !== '' || obj.AirWayData.AirClass !== '' || obj.AirWayData.DentitionList.length > 0 || obj.AirWayData.Dentition !== '' || obj.AirWayData.AirNotes !== '')) || obj.CNSData.length > 0 ||
            obj.RespiratoryData.length > 0 || obj.SocialData.length > 0 || obj.SystemichistoryData.length > 0 || obj.ChemistryData.length > 0 || obj.ChemistryNotes !== '' || obj.OtherSystemsData.length > 0) {
            content.push(getHAndPTable());
        }
        if (obj.HandpLabdata.length > 0) {
            content.push(getHandPLabsData(obj.HandpLabdata));
        }
        if (obj.AirWayData.AirIsNormal !== undefined) {
            if (obj.AirWayData.AirIsNormal == true || obj.AirWayData.AirROMTMS !== '' || obj.AirWayData.AirROMNECKAP !== '' || obj.AirWayData.AirROMNECKLAT !== '' || obj.AirWayData.AirClass !== '' || obj.AirWayData.DentitionList.length > 0 || obj.AirWayData.Dentition !== '' || obj.AirWayData.AirNotes !== '') {
                content.push(getHandPAirWayData(obj.AirWayData));
            }
        }
        if (obj.CNSData.length > 0) {
            content.push(getHandPCNSData(obj.CNSData));
        }
        if (obj.RespiratoryData.length > 0) {
            content.push(getHandPRespiratoryData(obj.RespiratoryData));
        }
        if (obj.SocialData.length > 0) {
            content.push(getHandPSocialData(obj.SocialData));
        }
        if (obj.SystemichistoryData.length > 0) {
            content.push(getHandPSystemicHistoryData(obj.SystemichistoryData));
        }
        if (obj.ChemistryData.length > 0 || obj.ChemistryNotes !== '') {
            content.push(getHandPChemistryData(obj.ChemistryData, obj.ChemistryNotes));
        }
        //if (obj.OtherSystemsData.length > 0) {
        //    content.push(getHandPOtherSystemsData(obj.OtherSystemsData));
        //}
        if (obj.PrevAnesthetics.length > 0 || obj.AssessmentASAObj.Value !== '' || obj.AssessmentASAObj.Notes !== '' || obj.AnesthesiaTypelist.lenth > 0 || obj.AnesthesiaDosage !== '' || obj.AnesthetistName !== '' || obj.AnesthetistNotes !== '') {
            content.push(getAnesthesiaEvaluationInfoTable());
        }
        if (obj.PrevAnesthetics.length > 0) {
            content.push(getPrevAnestheticsData(obj.PrevAnesthetics));
        }
        if (obj.AssessmentASAObj.Value !== '' || obj.AssessmentASAObj.Notes !== '') {
            content.push(getAssessmentASAData(obj.AssessmentASAObj));
        }
        if (obj.AnesthesiaTypelist.length > 0 || obj.AnesthesiaDosage !== '' || obj.AnesthetistName !== '' || obj.AnesthetistNotes !== '') {
            content.push(getAnesthesiaTypeData(obj.AnesthesiaTypelist, obj.AnesthesiaDosage, obj.AnesthetistName, obj.AnesthetistNotes));
        }
        if (obj.MedicationsDetails.length > 0 || obj.LabInvestigationsList.length > 0) {
            content.push(getPhysianOrdersData(obj.MedicationsDetails, obj.LabInvestigationsList));
        }
        if (obj.AnesthesiaStatus !== '' || obj.AnesthesiaReviewedName !== '') {
            content.push(getAnesthesiaStatusData(obj.AnesthesiaStatus, obj.AnesthesiaReviewedName, obj.AnesthesiaSuffix, obj.AnesthesiaLicenseNo, obj.AnesthetistReviewedDate));
        }
        if (obj.AlderetScoreDetails.length > 0 || obj.PreOpCallDetails.length > 0 || obj.Ascpatientpopupsavearray.length > 0) {
            content.push(getPreOpNotesTable());
        }
        if (obj.AlderetScoreDetails.length > 0) {
            var AlderetScoreItems = getAlderetScoreData(obj.AlderetScoreDetails, obj.TotalAlderetScore);
            content.push(AlderetScoreItems);
        }
        if (obj.PreOpCallDetails.length > 0) {
            var PreOpCallDetailItems = getPreOpCallDetailData(obj.PreOpCallDetails);
            content.push(PreOpCallDetailItems);
        }
        if (obj.Ascpatientpopupsavearray.length > 0) {
            var PreoppatientItems = getPreoppatientData(obj.Ascpatientpopupsavearray);
            content.push(PreoppatientItems);
        }
        if (obj.ReviewedByName !== '') {
            //content.push(getIntraOpReviwedByInfoTableForASC());
            content.push(getReviewedByName(obj.ReviewedByName, obj.ReviewedDate, obj.ReviewedTime, obj.SuffixName, obj.LicenseNo));
        }
        if (obj.SignOffUserDetails.length > 0) {
            content.push(getIntraOpSignedOffByInfoTableForASC());
            content.push(getSignedOffByData(obj.SignOffUserDetails));
        }

        let CurrentDate = $filter('date')(new Date(), "MM-dd-yyyy");
        let CurrentTime = $filter('date')(new Date(), " hh:mm:a");
        let docdefination = {
            content: content,
            defaultStyle: {
                font: 'Roboto'
            },
            defaultStyle: {
                font: "Roboto"
            },
            content: content,
            footer: {
                columns: [
                    { text: 'Printed by ' + obj.CreatedBy + ' / ' + 'Date: ' + CurrentDate + ' / ' + 'Time: ' + CurrentTime, alignment: 'right', fontSize: 7, margin: [0, 0, 15, 0] }
                ]
            },
            pageSize: 'LETTER',
            pageOrientation: 'portrait',//portrait landscape
            pageMargins: [25, 10, 25, 20],
            styles: {
                header: {
                    fontSize: 20,
                    bold: true,
                    background: "#eaeaea",
                    alignment: 'center',
                    color: "black",

                },
                sectionHeader: {
                    fontSize: 16,
                    bold: true,
                    margin: [0, 10, 0, 5],
                },
                subSectionHeader: {
                    fontSize: 14,
                    bold: true,
                    margin: [20, 5, 0, 5],
                },
                tableExample: {
                    margin: [0, 5, 0, 15]
                },
                subheader: {
                    fontSize: 16,
                    bold: true,
                    margin: [0, 10, 0, 5]
                },
            },
        }
        pdfMake.createPdf(docdefination).print();
    };
