    function getPostOpRecoveryTimes(obj) {
        let bodyItem = [];
        let hfont = 9;

        // Recovery start and end times
        let RecoveryTimesArary = [];
        let tempRecoveryArray = [];
        //if (obj.RecoveryStartTime != "" || obj.RecoveryStopTime != "") {
        //    tempRecoveryArray.push({ text: 'Recovery : ', alignment: 'left', bold: true, fontSize: hfont });
        //}
        if (obj.RecoveryStartTime != "") {
            tempRecoveryArray.push({ text: 'In Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempRecoveryArray.push({ text: obj.RecoveryStartTime + '    ', alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.RecoveryStopTime != "") {
            tempRecoveryArray.push({ text: 'Out Time - ', alignment: 'left', bold: true, fontSize: hfont });
            tempRecoveryArray.push({ text: obj.RecoveryStopTime, alignment: 'left', bold: false, fontSize: hfont });
        }

        if (obj.RecoveryStartTime != "" || obj.RecoveryStopTime != "") {
            RecoveryTimesArary.push({ text: tempRecoveryArray });
            bodyItem.push(RecoveryTimesArary);
        }

        let RecoveryTimesTable = {
            table: {
                widths: '*',
                body: bodyItem
            },
            layout: 'noBorders'
        };
        return RecoveryTimesTable;
    }

