                    if (mitem.IvAccessGivenByName !== '' || mitem.IvAccessGivenByTime !== '' || mitem.IvAccessGivenByDate !== '') {
                        IvAccessGivenByName1 = 'User : ';
                    }
                    if (mitem.IvAccessGivenByDate !== '') {
                        IvAccessGivenByDate1 = mitem.IvAccessGivenByDate + ' , '
                    }
