    function getHandOffInfoData(Reviewed, Time, Remarks, PreOpHandOffFromName) {
        var hFont = 9;

        var HandOffArray = [];
        var handOffReviewedBy = '';
        var handOffTime = '';
        var handoffRemarks = '';
        var HandOffFromName = '';
        var HandOff = '';
        PreOpHandOffFromName = PreOpHandOffFromName || '';

        if (PreOpHandOffFromName !== '' || Reviewed !== '') {
            HandOff = 'Hand-Off  : ';
        }
        Reviewed = Reviewed || '';
        if (PreOpHandOffFromName !== '') {
            HandOffFromName = ' From  : ';
        }
        if (Reviewed !== '') {
            handOffReviewedBy = ' To : ';
        }
        Time = Time || '';
        if (Time !== '') {
            handOffTime = 'Time : ';
        }

        Remarks = Remarks || ''
        if (Remarks !== '') {
            handoffRemarks = 'Remarks : ';
        }

        var Notes1 = [];
        if (Reviewed != '' || Time !== '' || Remarks !== '' || PreOpHandOffFromName != '') {
            var A1 = [];
            A1.push({ text: "Hand - Off Notes", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right' },
                {
                    text: [
                        { text: HandOff, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                        { text: HandOffFromName, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                        { text: PreOpHandOffFromName + ' ', fontSize: hFont, alignment: 'left', color: "black", bold: false },

                        { text: handOffReviewedBy, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                        { text: Reviewed + ' ', fontSize: hFont, alignment: 'left', color: "black", bold: false },
                        { text: handOffTime, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                        { text: Time + ' ', fontSize: hFont, alignment: 'left', color: "black", bold: false },
                        { text: handoffRemarks, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                        { text: Remarks, fontSize: hFont, alignment: 'left', color: "black", bold: false }

                    ]
                });
            Notes1.push(A1);
        }


        var A1 = [];
        A1.push({
            table: {
                widths: [100, '*'],
                body: Notes1,
            }, layout: 'noBorders'
        });
        HandOffArray.push(A1);

        var PrescriptionTable = {
            table: {
                widths: ['*'],
                body: HandOffArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        return PrescriptionTable;
    }

    function getPatientIdentifier(name, date) {
        var hFont = 9;



        var IdentifierName = '';
        var IdentifierDOB = '';
        var IdentifierArray = [];
        //Reviewed = Reviewed || '';
        if (name !== '') {
            IdentifierName = 'Name : ';
        }
        date = date || '';
        if (date !== '') {
            date = $filter("date")(date, "MM-dd-yyyy");
            IdentifierDOB = 'DOB : ';
        }


        var Notes1 = [];
        if (name != '' || date !== '') {
            var A1 = [];
            A1.push({ text: "Patient Identifier", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right' },
                {
                    text: [{ text: IdentifierName, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                    { text: name + ' ', fontSize: hFont, alignment: 'left', color: "black", bold: false },
                    { text: IdentifierDOB, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                    { text: date + ' ', fontSize: hFont, alignment: 'left', color: "black", bold: false },
                        //{ text: handoffRemarks, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                        //{ text: Remarks, fontSize: hFont, alignment: 'left', color: "black", bold: false }

                    ]
                });
            Notes1.push(A1);
        }


        var A2 = [];
        A2.push({
            table: {
                widths: [100, '*'],
                body: Notes1,
            }, layout: 'noBorders'
        });
        IdentifierArray.push(A2);

        var PrescriptionTable = {
            table: {
                widths: ['*'],
                body: IdentifierArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        return PrescriptionTable;
    }


