                if (Bitem.DiabetesTime !== '') {
                    Ind = ' at ';
                }
                Diabetesandtime = Bitem.DiabetesResult + Ind + Bitem.DiabetesTime;
                Bitem.DiabetesGivenByName = Bitem.DiabetesGivenByName || '';
                var A11 = [];
                A11.push({ text: Diabetesandtime, margin: [0, 0, 0, 5], bold: false, fontSize: 8 },
                    { text: Bitem.DiabetesGivenByName + LicNo, color: '#000000', fontSize: 8 });

