                pitem.PatientNotes = LatestpatientNotes || [];
                if (pitem.PatientBaseInfo.Occupation != '') {
                    pitem.PatientBaseInfo.OccupationNotes = pitem.PatientBaseInfo.Occupation || '';
                }
                pitem.PatientBaseInfo.OccupationNotes = pitem.PatientBaseInfo.OccupationNotes || '';
                pitem.PatientBaseInfo.MobileNo = pitem.PatientBaseInfo.MobileNo || '';
                if (pitem.PatientBaseInfo.MobileNo != '') {
                    var obj = eHnoteUserDataService.UsMobileFormatChange(pitem.PatientBaseInfo.MobileNo);
                    pitem.PatientBaseInfo.MobileNo = obj.UsFormatMobileNumber;
                }
                pitem.PatientBaseInfo.ContactNo = pitem.PatientBaseInfo.ContactNo || '';
                if (pitem.PatientBaseInfo.ContactNo.length > 3) {
                    var obj = eHnoteUserDataService.UsMobileFormatChange(pitem.PatientBaseInfo.ContactNo);
                    pitem.PatientBaseInfo.ContactNo = obj.UsFormatMobileNumber;
                } else {
                    pitem.PatientBaseInfo.ContactNo = "";
                }
                pitem.Addressinfo = pitem.PatientBaseInfo.PatientAddress || {};
                pitem.PCPDoctorName = filteredArray[0].PCPDoctorName || '';
                pitem.PatientBaseInfo.CreatedBy = filteredArray[0].DoctorFullName || '';
                pitem.AppointmentTime = filteredArray[0].StartTime || '';
                pitem.AppointmentDate = filteredArray[0].ConsultationDt || '';
