    function getPatientFacesheetDetails(localArray, breakindex, scopeObjLength) {
        var breakindex = breakindex || 0;
        var breaktype = 'after';
        if (breakindex == (scopeObjLength - 1)) {
            breaktype = undefined;
        }

        localArray = localArray || [];
        if (localArray.length === 0) {
            return;
        }
        var filter = localArray.Patient || {};
        var Organ = '';
        var Organname = '';
        var Eyeorganid = '';
        var EyeOrganname = '';
        filter.OrganId = filter.OrganId || 0;
        filter.SurgeryEyeStatusId = filter.SurgeryEyeStatusId || 0;
        Organ = filter.OrganId;
        Eyeorganid = filter.SurgeryEyeStatusId;

        if (Eyeorganid === 1) {
            EyeOrganname = '1st Eye'
        }
        if (Eyeorganid === 2) {
            EyeOrganname = '2nd Eye'
        }
        if (Organ === 1) {
            Organname = 'Right Eye ';
        }
        if (Organ === 2) {
            Organname = 'Left Eye ';
        }
        if (Organ === 3) {
            Organname = 'Both Eyes ';
        }

        var DOB = '';
        DOB = $filter("date")((filter.DOB), "MM-dd-yyyy");
        var filterallaergy = localArray.PatientAllergy || [];
        var cFont = 20;
        var hfont = 40;
        var bodyItem = [];
        if (EyeOrganname != '') {
            EyeOrganname = ' - ' + EyeOrganname;
        }

        var VisitReason = "";
        VisitReason = filter.VisitReason || '';

        var headring = [{
            text: ' Patient Details', alignment: 'left', fontSize: cFont, bold: true,
            fillColor: '#eaeaea', border: [false, true, false, true]
        }];
        bodyItem.push(headring);

        var Row1 = [

            { text: filter.FullName, alignment: 'left', color: "black", fontSize: hfont, bold: true, border: [false, false, false, false] },

        ];
        bodyItem.push(Row1);
        var Row2 = [
            { text: DOB, alignment: 'left', color: "black", bold: true, fontSize: hfont, border: [false, false, false, false] },
        ];
        bodyItem.push(Row2);

        var Row3 = [
            { text: VisitReason, alignment: 'left', color: "black", bold: true, fontSize: hfont, border: [false, false, false, false] },
        ];
        bodyItem.push(Row3);

        var Row4 = [
            { text: Organname + EyeOrganname, alignment: 'left', color: "black", bold: true, fontSize: hfont, border: [false, false, false, false] },
        ];
        bodyItem.push(Row4);

        var headring = [{
            text: 'Allergies', alignment: 'left', fontSize: cFont, bold: true,
            fillColor: '#eaeaea', border: [false, true, false, true]
        }];
        bodyItem.push(headring);

        if (filterallaergy.length > 0) {
            var AllergyName = '';
            angular.forEach(filterallaergy, function (mitem) {
                if (mitem.StatusId === 1 || mitem.AllergyId === 2 || mitem.AllergyId === 1) {
                    mitem.AllergyName = mitem.AllergyName || '';
                    if (mitem.AllergyName !== '') {
                        if (AllergyName == '') {
                            AllergyName = mitem.AllergyName;
                        } else {
                            AllergyName += ' , ' + mitem.AllergyName;
                        }
                    }
                }
            });
            if (AllergyName !== '') {
                var Row1 = [
                    { text: AllergyName, alignment: 'left', color: "black", bold: true, fontSize: 40, border: [false, false, false, false] },

                ];
                bodyItem.push(Row1);
            }
        }


        var ChecklistTable = {
            style: 'tableExample',
            table: {
                widths: ['*'],
                body: bodyItem
            },
            layout: 'lightHorizontalLines',
            pageBreak: breaktype
        };

        return ChecklistTable;
    }


