    function getPreAdmCoordinatrDataTable(Object) {
        var hFont = 10;
        var bodyItem = [];
        var CoordinatorArray = [];
        if (Object.length == 0) {
            return;
        }

        let Line1 = [];
        Line1.push({ text: 'Questions', fontSize: hFont, alignment: 'left', color: "black", bold: true, },
            { text: 'OD (Right)', fontSize: hFont, alignment: 'center', color: "black", bold: true, },
            { text: 'OS (Left)', fontSize: hFont, alignment: 'center', color: "black", bold: true, },
        );

        CoordinatorArray.push(Line1);

        angular.forEach(Object, function (item, index) {
            let Line2 = [];
            Line2.push(
                { text: index + 1 + '.' + item.Description, fontSize: hFont, alignment: 'left', color: "black", bold: false, },
                { text: item.OdValue, fontSize: hFont, alignment: 'center', color: "black", bold: false, },
                { text: item.OsValue, fontSize: hFont, alignment: 'center', color: "black", bold: false, },
            );
            CoordinatorArray.push(Line2);
        });

        var Coordinatortable = {
            table: {
                widths: [300, 80, '*'],
                body: CoordinatorArray,
            }, layout: 'noBorders'
        };
        bodyItem.push(Coordinatortable);
        return bodyItem;
    }
    function getPreAdmCounsellerCoordinatrDataTable(Object, Obj) {
        var hFont = 10;
        var bodyItem = [];
        var CoordinatorArray = [];
        if (Object.length == 0) {
            return;
        }

        angular.forEach(Object, function (item, index) {
            var Value = '';
            var ValueCounter = 0;
            var QuestionValueId = 0;

            if (item.Notes !== '') {
                ValueCounter++;
            }

            if (item.CoOrdinatorQuestionValues.length > 0) {
                angular.forEach(item.CoOrdinatorQuestionValues, function (vitem) {
                    if (vitem.IsChecked) {
                        ValueCounter++;
                        QuestionValueId = vitem.QuestionValueId
                        if (Value == '') {
                            Value = vitem.Value;
                        } else {
                            Value = Value + ' , ' + vitem.Value;
                        }
                    }
                });
            }

            if (ValueCounter !== 0) {
                let Line1 = [];
                Line1.push(
                    { text: index + 1 + '.' + item.Description, fontSize: hFont, alignment: 'left', color: "black", bold: false, },
                    { text: Value, fontSize: hFont, alignment: 'center', color: "black", bold: false, },
                );
                CoordinatorArray.push(Line1);
            }

            if (QuestionValueId == 4) {
                if (Obj.ClearanceDoctorName !== '' || Obj.ClearanceReqDate !== null || Obj.ClearanceRecievedDate !== null) {
                    var ClearanceDoctorName = '';
                    var ClearanceReqDate = '';
                    var ClearanceRecievedDate = '';

                    Obj.ClearanceReqDate = Obj.ClearanceReqDate || '';
                    Obj.ClearanceRecievedDate = Obj.ClearanceRecievedDate || '';

                    if (Obj.ClearanceDoctorName !== '') {
                        ClearanceDoctorName = 'Doctor : '
                    }
                    if (Obj.ClearanceReqDate !== '') {
                        ClearanceReqDate = 'Date Of Request : '
                    }
                    if (Obj.ClearanceReqDate !== '') {
                        ClearanceRecievedDate = 'Date Of Recieved  : '
                    }
                    let Line2 = [];
                    Line2.push(
                        { text: '', fontSize: hFont, alignment: 'left', color: "black", bold: false, },
                        {
                            text: [{ text: ClearanceDoctorName, fontSize: 9, alignment: 'left', color: "black", bold: true, },
                            { text: Obj.ClearanceDoctorName + '   ', fontSize: 9, alignment: 'left', color: "black", bold: false, },
                            { text: ClearanceReqDate, fontSize: 9, alignment: 'left', color: "black", bold: true, },
                            { text: Obj.ClearanceReqDate + '   ', fontSize: 9, alignment: 'left', color: "black", bold: false, },
                            { text: ClearanceRecievedDate, fontSize: 9, alignment: 'left', color: "black", bold: true, },
                            { text: Obj.ClearanceRecievedDate, fontSize: 9, alignment: 'left', color: "black", bold: false, },
                            ],
                        },
                    );
                    CoordinatorArray.push(Line2);
                }
            }
            if (QuestionValueId == 33) {
                if (Obj.DispensedByUserName !== '' || Obj.DispenseDate !== null || Obj.DispenseTime !== '') {
                    var DispensedByUserName = '';
                    var DispenseDate = '';
                    var DispenseTime = '';

                    Obj.DispenseDate = Obj.DispenseDate || '';

                    if (Obj.DispensedByUserName !== '') {
                        DispensedByUserName = 'Dispensed By : '
                    }
                    if (Obj.DispenseDate !== '') {
                        DispenseDate = 'Date : '
                    }
                    if (Obj.DispenseTime !== '') {
                        DispenseTime = 'Time : '
                    }
                    let Line3 = [];
                    Line3.push(
                        { text: '', fontSize: hFont, alignment: 'left', color: "black", bold: false, },
                        {
                            text: [{ text: DispensedByUserName, fontSize: 9, alignment: 'left', color: "black", bold: true, },
                            { text: Obj.DispensedByUserName + '   ', fontSize: 9, alignment: 'left', color: "black", bold: false, },
                            { text: DispenseDate, fontSize: 9, alignment: 'left', color: "black", bold: true, },
                            { text: Obj.DispenseDate + '   ', fontSize: 9, alignment: 'left', color: "black", bold: false, },
                            { text: DispenseTime, fontSize: 9, alignment: 'left', color: "black", bold: true, },
                            { text: Obj.DispenseTime, fontSize: 9, alignment: 'left', color: "black", bold: false, },
                            ],
                        },
                    );
                    CoordinatorArray.push(Line3);
                }
            }
            if (item.Notes !== '') {
                let Line4 = [];
                Line4.push(
                    {
                        text: [{ text: 'Notes : ', fontSize: 9, alignment: 'left', color: "black", bold: true, },
                        { text: item.Notes, fontSize: 9, alignment: 'left', color: "black", bold: false, },
                        ], colSpan: 2
                    }
                );
                CoordinatorArray.push(Line4);
            }
        });

        var Coordinatortable = {
            table: {
                widths: [200, '*'],
                body: CoordinatorArray,
            }, layout: 'noBorders'
        };
        bodyItem.push(Coordinatortable);
        return bodyItem;
    }
