    function getYagTemplateProcedureData(ProcedureName, SiteName, VisitReason) {
        var hFont = 9;
        var ProcedureArray = [];
        var ProcedureListArray = [];

        VisitReason = VisitReason || '';
        ProcedureName = ProcedureName || '';
        SiteName = SiteName || '';

        if (SiteName == '' && ProcedureName == '' && VisitReason == '') {
            return;
        }

        if (VisitReason != '') {
            let Line3 = [];
            Line3.push(
                { text: 'Visit Reason', fontSize: 9, alignment: 'left', color: "black", bold: false, },
                { text: VisitReason, fontSize: 9, alignment: 'left', color: "black", bold: true, },
            );
            ProcedureArray.push(Line3);
        }


        if (ProcedureName != '') {
            let Line3 = [];
            Line3.push(
                { text: 'Procedure Name ', fontSize: 9, alignment: 'left', color: "black", bold: false, },
                { text: ProcedureName, fontSize: 9, alignment: 'left', color: "black", bold: true, },
            );
            ProcedureArray.push(Line3);
        }

        if (SiteName != '') {
            let Line4 = [];
            Line4.push(
                { text: 'Site ', fontSize: 9, alignment: 'left', color: "black", bold: false, },
                { text: SiteName, fontSize: 9, alignment: 'left', color: "black", bold: true, },
            );
            ProcedureArray.push(Line4);
        }
        var A1 = [];
        A1.push({ text: "Procedure", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right', margin: [0, 0, 0, 0], border: [false, true, true, true] }, {
            table: {
                widths: [100, '*'],
                body: ProcedureArray,
            }, layout: 'noBorders'
        });
        ProcedureListArray.push(A1);

        var PrescriptionTable = {
            table: {
                widths: [80, '*'],
                body: ProcedureListArray,
            }, layout: {
                hLineWidth: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                },
                vLineWidth: function (i, node) {
                    return 0;
                },
                hLineColor: function (i, node) {
                    return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                },
                vLineColor: function (i, node) {
                    return '';
                }
            }
        };
        return PrescriptionTable;
    }

