    function getIntraOpNurseNotes(Notes, PatientTolerated) {
        var hFont = 9;
        var bodyItem = [];
        var IntraOpNurseNotesArray = [];
        Notes = Notes || '';
        var patientdescription = '';
        if (PatientTolerated) {
            patientdescription = 'Patient tolerated the surgery well';
        }
        //if (Notes == '' && !PatientTolerated) {
        //    return;
        //}

        if (patientdescription !== '') {
            let Line3 = [];
            Line3.push({
                text: [{ text: '', alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                { text: patientdescription, fontSize: hFont, alignment: 'left', color: "black", bold: false },
                ]
            },
            );
            IntraOpNurseNotesArray.push(Line3);
        }

        let Line2 = [];
        Line2.push({
            text: [{ text: 'Notes: ', alignment: 'left', color: "black", fontSize: hFont, bold: true, },
            { text: Notes, fontSize: hFont, alignment: 'left', color: "black", bold: false },
            ]
        },
        );
        IntraOpNurseNotesArray.push(Line2);

        var IntraOpNurseArray = {
            table: {
                widths: ['*'],
                body: IntraOpNurseNotesArray,
            }, layout: 'noBorders'
        };
        bodyItem.push(IntraOpNurseArray);
        return bodyItem;

    }
    this.GenerateDoctorNotesPrint = function (obj) {
        var doctorinfo = eHnoteMasterDataService.getUserInfo();
        let printSettingInfo = eHnoteMasterDataService.getPrintSettingSpecific("OT").PageSettings;
        let emptyRow = getEmptyTable();
        let data = printSettings;
        let pageSettings = {
            "marginLeft": 40,
            "marginTop": 100,
            "marginRight": 40,
            "marginBottom": 10
        };
        let headerHeight = 100;
        let footerHeight = 100;
        let docSign = "";
        let isDefaultDocSign = "";
        let content = [];
        contentSetting = setContentSettings();
        if (data !== undefined) {
            pageSettings = data.JsonSetting.pageSettings;
            headerHeight = data.JsonSetting.clinicSettings.headerSettings.dimension.height;
            footerHeight = data.JsonSetting.clinicSettings.footerSettings.dimension.height;
            contentSetting = data.JsonSetting.clinicSettings.contentSettings;
            docSign = data.JsonSetting.clinicSettings.footerSettings.custFootSign;
            isDefaultDocSign = data.JsonSetting.clinicSettings.footerSettings.isFootSignDefault;
            if (printSettingInfo.PageSize === "A4") {
                defaultFontSize = 10;
            } else {
                printPageSize = "A4";
                defaultFontSize = 10;
            }
        }



        //content.push(getPatientBranchDetailsTableForASC(obj));
        content.push(getAppointmentBranchDetailsTable(obj));
        content.push(getPatientDetailsTable());
        content.push(getPatientDetailsTableForASC(obj));
        content.push(getPatientSurgeryDetailsTable());
        content.push(getPatientSurgeryDetailsTableForASC(obj));

        if (obj.FaceSheetCheckList.length > 0) {
            content.push(getPreopSurgeonverification(obj.SurgeonVerifiedUserName));
            var DoctorsNotesData = getDoctorsNotesData(obj.FaceSheetCheckList, obj.PreviousValuesObj, obj.PreviousCDAODValue, obj.PreviousCDAOSValue, obj.PreviousCDAValueGivenDate, obj.TonometryArray)
            if (DoctorsNotesData) {
                content.push(DoctorsNotesData);
            }
        }

        if (obj.FacesheetLastSignOffUserDetails.length > 0 && obj.FaceSheetChartStatus === 'E') {
            content.push(getIntraOpSignedOffByInfoTableForASC());
            content.push(getSignedOffByData(obj.FacesheetLastSignOffUserDetails));
        }
        var SurgeryDate = '';
        var Patientdob = '';
        if (obj.SurgeryDate !== '') {
            SurgeryDate = $filter('date')(obj.SurgeryDate, "MM-dd-yyyy");
        }

        if (obj.PatientDOB) {
            Patientdob = $filter('date')(obj.PatientDOB, "MM-dd-yyyy");
        }

        let CurrentDate = $filter('date')(new Date(), "MM-dd-yyyy");
        let CurrentTime = $filter('date')(new Date(), "hh:mm a");
        let docdefination = {
            content: content,
            defaultStyle: {
                font: 'Roboto'
            },
            defaultStyle: {
                font: "Roboto"
            },
            footer: {
                columns: [
                    { text: 'Name : ' + obj.Name + ' / MR.No : ' + obj.PatientDisplayId + ' / DOB : ' + Patientdob + ' / DOS : ' + SurgeryDate, alignment: 'left', fontSize: 8, margin: [15, 0, 15, 0] },
                    { text: 'Printed by ' + obj.CreatedBy + ' / Date: ' + CurrentDate + ' / Time: ' + CurrentTime, alignment: 'right', fontSize: 8, margin: [0, 0, 15, 0] }
                ]
            },
            pageSize: 'LETTER',
            pageOrientation: 'portrait',//portrait landscape
            pageMargins: [25, 10, 25, 20],
            styles: {
                header: {
                    fontSize: 20,
                    bold: true,
                    background: "#eaeaea",
                    alignment: 'center',
                    color: "black",

                },
                sectionHeader: {
                    fontSize: 16,
                    bold: true,
                    margin: [0, 10, 0, 5],
                },
                subSectionHeader: {
                    fontSize: 14,
                    bold: true,
                    margin: [20, 5, 0, 5],
                },
                tableExample: {
                    margin: [0, 5, 0, 15]
                },
                subheader: {
                    fontSize: 16,
                    bold: true,
                    margin: [0, 10, 0, 5]
                },
            },
        }

        pdfMake.createPdf(docdefination).print();

    }

