    function getAllOrdersIVAccessDetails(IVAccessDetailsList, IVCondition) {
        var IVdetails = [];
        var IVdetailsArray = [];
        var hFont = 9;

        if (IVAccessDetailsList.length > 0) {
            angular.forEach(IVAccessDetailsList, function (mitem, index) {

                var checklistname = '';
                var value = '';
                var site1 = '';
                var patencyStatus1 = '';
                var IVArm1 = '';
                var IVNamestring = '';
                var needleSize1 = '';

                var IvAccessGivenByName1 = '';
                var IvAccessGivenByDate1 = '';

                mitem.IvAccessGivenByName = mitem.IvAccessGivenByName || '';
                mitem.IvAccessGivenByTime = mitem.IvAccessGivenByTime || '';
                mitem.IvAccessGivenByDate = mitem.IvAccessGivenByDate || '';

                mitem.IVSiteName = mitem.IVSiteName || '';
                mitem.PatencyStatus = mitem.PatencyStatus || '';
                mitem.IVArm = mitem.IVArm || '';
                mitem.IVBlockedArray = mitem.IVBlockedArray || [];


                if (IVCondition.length > 0) {
                    angular.forEach(IVCondition, function (item, index) {
                        item.CheckListName = item.CheckListName || '';
                        if (item.CheckListName !== '') {
                            checklistname = item.CheckListName + ' : ';
                        }

                    })
                }

                if (mitem.ConditionList.length > 0) {
                    var finalValues = [];

                    angular.forEach(mitem.ConditionList, function (item, index) {
                        finalValues.push(item.Value || '');
                        var finalvalue = (finalValues.length > 0) ? finalValues.join(',') : '';
                        if (finalvalue !== '') {
                            value = finalvalue;
                        }
                    })
                }
                if (value != '') {
                    checklistname = checklistname || "";
                } else {
                    checklistname = '';
                }

                if (mitem.IVNeedleSizeName !== '') {
                    needleSize1 = 'Size of the canula : ';
                }

                if (mitem.IvAccessGivenByDate !== '') {
                    mitem.IvAccessGivenByDate = $filter("date")(mitem.IvAccessGivenByDate, "MM-dd-yyyy");
                }

                if (mitem.IvAccessGivenByName !== '' || mitem.IvAccessGivenByTime !== '') {
                    IvAccessGivenByName1 = 'User : ';
                }

                if (mitem.IVSiteName !== '') {
                    site1 = 'Site : ';
                }

                if (mitem.PatencyStatus !== '') {
                    patencyStatus1 = 'Patency Status : '
                }
                if (mitem.IVArm !== '') {
                    IVArm1 = 'Location : '
                }


                if (mitem.PatencyStatus == 'Blocked') {
                    if (mitem.IVBlockedArray.length > 0) {
                        var IVfiter = $filter('filter')(mitem.IVBlockedArray, { 'IsSelected': true }, true) || [];
                        angular.forEach(IVfiter, function (item) {
                            if (IVNamestring == '') {
                                IVNamestring = item.IVSiteMarkingName;
                            } else {
                                IVNamestring = IVNamestring + ' , ' + item.IVSiteMarkingName;
                            }
                        });
                    }
                }

                if (mitem.IVSiteName !== '' || value !== '' || mitem.PatencyStatus !== '' || IVNamestring !== '' || mitem.IVNeedleSizeName !== '' || mitem.IVArm !== '' || mitem.IvAccessGivenByName !== '' || mitem.IvAccessGivenByTime !== '') {
                    var H11 = [];

                    var ind = 'IV' + (index + 1);

                    H11.push({
                        text: [
                            { text: ind + "  ", fontSize: hFont, alignment: 'center', color: "black", bold: true, border: [false, false, false, false] },
                            { text: site1, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                            { text: mitem.IVSiteName + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: false, },

                            { text: checklistname, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                            { text: value + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: false, },

                            { text: patencyStatus1, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                            { text: mitem.PatencyStatus + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: false, },

                            { text: IVNamestring + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: false },

                            { text: needleSize1, alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                            { text: mitem.IVNeedleSizeName + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: false, },

                            { text: IVArm1 + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                            { text: mitem.IVArm + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: false, },

                            { text: IvAccessGivenByName1 + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: true, },
                            { text: mitem.IvAccessGivenByName + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: false, },
                            { text: IvAccessGivenByDate1 + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: false, },
                            { text: mitem.IvAccessGivenByTime + '  ', alignment: 'left', color: "black", fontSize: hFont, bold: false, },
                        ]
                    }
                    )
                    IVdetails.push(H11);
                }
            });


        }

        if (IVdetails.length > 0) {
            var A1 = [];
            A1.push({ text: "IV Access", fillColor: "#F1F1F1", fontSize: hFont, alignment: 'right', margin: [0, 5, 0, 0], border: [false, true, true, true] }, {
                table: {
                    widths: ['*'],
                    body: IVdetails,
                }, layout: 'noBorders'
            });
            IVdetailsArray.push(A1);
        }

        if (IVdetailsArray.length > 0) {
            var PrescriptionTable = {
                table: {
                    widths: [100, '*'],
                    body: IVdetailsArray,
                }, layout: {
                    hLineWidth: function (i, node) {
                        return (i === 0 || i === node.table.body.length) ? 0.5 : 0.5;
                    },
                    vLineWidth: function (i, node) {
                        return 0;
                    },
                    hLineColor: function (i, node) {
                        return (i === 0 || i === node.table.body.length) ? 'gray' : 'gray';
                    },
                    vLineColor: function (i, node) {
                        return '';
                    }
                }
            };
            return PrescriptionTable;
        }
    }


