    function getSubscriberDependentInfo(obj) {

        var body = [];

        // ===== Patient Name Header =====
        body.push([
            {
                text: (obj.InsuredName || '').toUpperCase(),
                colSpan: 2,
                bold: false,
                fontSize: 10,
                margin: [6, 2, 6, 2],
                border: [true, true, true, true]
            },
            {}
        ]);

        var addressBlock = {
            stack: [
                { text: 'Address:', bold: false, fontSize: 10, margin: [0, 0, 0, 2] },
                { text: obj.InsuredAddress1 || '', bold: true, fontSize: 10 },
                { text: obj.Address2 || '', bold: true, fontSize: 10 },
                { text: obj.InsuredCity || '', bold: true, fontSize: 10 },
                { text: obj.InsuredState || '', bold: true, fontSize: 10 },
                { text: obj.InsuredZipCode || '', bold: true, fontSize: 10 }
            ],
            rowSpan: 6,
            margin: [6, 2, 6, 2],
            border: [true, true, true, true]
        };

        var PatientDoB = $filter('date')(obj.InsuredDOB, "MM-dd-yyyy") || "";
        var PlanBeginDate = $filter('date')(obj.PlanBeginDate, "MM-dd-yyyy") || "";
        var PlanEndDate = $filter('date')(obj.PlanEndDate, "MM-dd-yyyy") || "";

        function infoRow(label, value, isLast) {
            var infoCell = {
                columns: [
                    { text: label, width: 100, fontSize: 10, bold: false, color: 'black' },
                    { text: ':', width: 8, fontSize: 10, bold: false, color: 'black', alignment: 'center' },
                    { text: value || '', width: '*', fontSize: 10, bold: true, color: 'black' }
                ],
                columnGap: 0,
                margin: [4, 2, 4, 2],
                border: [true, true, true, true]
            };

            return isLast
                ? [infoCell, {}]
                : [infoCell, addressBlock];
        }

        // ===== Rows =====
        body.push(infoRow('DOB', PatientDoB, false));
        body.push(infoRow('Gender', obj.InsuredGender, false));
        body.push(infoRow('Policy ID', obj.PolicyNumber, false));
        body.push(infoRow('Group Number', obj.GroupNumber, false));
        body.push(infoRow('Plan Start Date', PlanBeginDate, false));
        body.push(infoRow('Plan End Date', PlanEndDate, true));

        return [{
            table: {
                widths: [230, '*'],
                body: body
            },
            layout: {
                fillColor: function () { return '#FAFAFA'; },
                hLineWidth: function (i, node) { return (i === 0 || i === node.table.body.length) ? 1 : 0; },
                vLineWidth: function (i, node) { return (i === 0 || i === node.table.widths.length) ? 1 : 0; },
                hLineColor: function () { return '#8C8C8C'; },
                vLineColor: function () { return '#8C8C8C'; },
                paddingLeft: function () { return 4; },
                paddingRight: function () { return 4; },
                paddingTop: function () { return 2; },
                paddingBottom: function () { return 2; }
            },
            margin: [0, 0, 0, 8]
        }];
    }


