    function getBenefitInfoSection(list) {

        var sections = [];

        // ===== Section Heading =====
        sections.push({
            text: 'Benefit Info',
            bold: false,
            fontSize: 10,
            margin: [0, 8, 0, 4]
        });

        list.forEach(function (item) {

            var body = [];

            // ===== Title (Example: B - Co-Payment) =====
            body.push([
                {
                    text: (item.ServiceTypeCode || '') + ' - ' + (item.BenifitTypeName || ''),
                    bold: true,
                    fontSize: 10,
                    margin: [6, 2, 6, 2],
                    border: [true, true, true, true]
                }
            ]);

            function infoRow(label, value) {
                return [
                    {
                        columns: [
                            { text: label, width: 100, fontSize: 10, bold: false, color: 'black' },
                            { text: ':', width: 8, fontSize: 10, bold: false, color: 'black', alignment: 'center' },
                            { text: value ? String(value) : '', width: '*', fontSize: 10, bold: true, color: 'black' }
                        ],
                        columnGap: 0,
                        margin: [6, 2, 6, 2],
                        border: [true, true, true, true]
                    }
                ];
            }

            // Coverage Level
            if (item.CoverageLevel) {
                body.push(infoRow('Coverage Level', item.CoverageLevel));
            }
            // Service Type
            if (item.ServiceCodeDescription) {
                body.push(infoRow('Service Type Code', item.ServiceCodeDescription));
            }
            // Description
            var description = item.PlanCoverageDescription || item.AdditionalInformation;
            if (description) {
                body.push(infoRow('Description', description));
            }
            // Benefit Amount
            if (item.BenifitAmount !== null && item.BenifitAmount !== undefined && item.BenifitAmount !== '') {
                body.push(infoRow('Benefit Amount', item.BenifitAmount));
            }
            // Time Period Qualifier
            if (item.TimePeriodQualifier) {
                body.push(infoRow('Time Period Qualifier', item.TimePeriodQualifier));
            }

            // ===== Card Container =====
            sections.push({
                unbreakable: true,
                table: {
                    headerRows: 0,
                    dontBreakRows: true,
                    widths: ['*'],
                    body: body
                },
                layout: {
                    fillColor: function () { return '#FAFAFA'; },
                    hLineWidth: function (i, node) { return (i === 0 || i === node.table.body.length) ? 0.8 : 0; },
                    vLineWidth: function (i, node) { return (i === 0 || i === node.table.widths.length) ? 0.8 : 0; },
                    hLineColor: function () { return '#9A9A9A'; },
                    vLineColor: function () { return '#9A9A9A'; },
                    paddingLeft: function () { return 4; },
                    paddingRight: function () { return 4; },
                    paddingTop: function () { return 2; },
                    paddingBottom: function () { return 2; }
                },
                margin: [0, 0, 0, 8]
            });

        });

        return sections;
    }


